// Nigeria Timezone Utility (WAT: UTC+1)

const NIGERIA_TIMEZONE = "Africa/Lagos"; // WAT is UTC+1

const getNigeriaDateParts = (date = new Date()) => {
  const formatter = new Intl.DateTimeFormat("en-GB", {
    timeZone: NIGERIA_TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });

  const parts = formatter.formatToParts(date).filter((part) => part.type !== "literal");
  return Object.fromEntries(parts.map((part) => [part.type, part.value]));
};

// Get current time in Nigeria as a local Date proxy
export const getNigeriaTime = () => {
  const parts = getNigeriaDateParts();
  return new Date(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour),
    Number(parts.minute),
    Number(parts.second)
  );
};

// Get YYYY-MM-DD in Nigeria time
export const getNigeriaDateKey = (date = new Date()) => {
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone: NIGERIA_TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  return formatter.format(date);
};

// Format time for Nigeria
export const formatNigeriaTime = (date = null) => {
  const targetDate = date || getNigeriaTime();
  return new Intl.DateTimeFormat("en-NG", {
    year: "numeric",
    month: "long",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    timeZoneName: "short",
  }).format(targetDate);
};

// Get greeting based on time
export const getGreeting = () => {
  const hour = getNigeriaTime().getHours();
  
  if (hour >= 5 && hour < 12) return { text: "Good Morning! 🌅", period: "morning" };
  if (hour >= 12 && hour < 17) return { text: "Good Afternoon! ☀️", period: "afternoon" };
  if (hour >= 17 && hour < 21) return { text: "Good Evening! 🌆", period: "evening" };
  return { text: "Good Night! 🌙", period: "night" };
};

// Check if it's a workout time
export const isWorkoutTime = () => {
  const hour = getNigeriaTime().getHours();
  return (hour >= 5 && hour < 9) || (hour >= 16 && hour < 19);
};

// Check if it's meal time
export const getMealTime = () => {
  const hour = getNigeriaTime().getHours();
  
  if (hour >= 6 && hour < 10) return "breakfast";
  if (hour >= 12 && hour < 14) return "lunch";
  if (hour >= 19 && hour < 21) return "dinner";
  return null;
};

// Get week day name in Nigeria style
export const getWeekDay = (date = null) => {
  const targetDate = date || getNigeriaTime();
  return new Intl.DateTimeFormat("en-NG", { weekday: "long" }).format(targetDate);
};

// Get week number
export const getWeekNumber = (date = null) => {
  const targetDate = date || getNigeriaTime();
  const firstDay = new Date(targetDate.getFullYear(), 0, 1);
  const pastDaysOfYear = (targetDate - firstDay) / 86400000;
  return Math.ceil((pastDaysOfYear + firstDay.getDay() + 1) / 7);
};

// Get month name
export const getMonthName = (date = null) => {
  const targetDate = date || getNigeriaTime();
  return new Intl.DateTimeFormat("en-NG", { month: "long" }).format(targetDate);
};

// Convert to Nigeria time string
export const toNigeriaTimeString = (date = null) => {
  const targetDate = date || getNigeriaTime();
  return targetDate.toLocaleTimeString("en-NG", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });
};

// Get start of day in Nigeria time
export const getStartOfDayNigeria = () => {
  const nigeriaTime = getNigeriaTime();
  nigeriaTime.setHours(0, 0, 0, 0);
  return nigeriaTime;
};

// Get end of day in Nigeria time
export const getEndOfDayNigeria = () => {
  const nigeriaTime = getNigeriaTime();
  nigeriaTime.setHours(23, 59, 59, 999);
  return nigeriaTime;
};

// Get start of week in Nigeria time
export const getStartOfWeekNigeria = () => {
  const nigeriaTime = getNigeriaTime();
  const day = nigeriaTime.getDay();
  const diff = nigeriaTime.getDate() - day;
  return new Date(nigeriaTime.setDate(diff));
};

// Get start of month in Nigeria time
export const getStartOfMonthNigeria = () => {
  const nigeriaTime = getNigeriaTime();
  return new Date(nigeriaTime.getFullYear(), nigeriaTime.getMonth(), 1);
};

// Format date for display
export const formatDateNigeria = (date = null) => {
  const targetDate = date || getNigeriaTime();
  return new Intl.DateTimeFormat("en-NG", {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(targetDate);
};
