import React, { useEffect, useMemo, useState } from "react";
import { NavLink, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const links = [
  { to: "/dashboard", icon: "⬡", label: "Dashboard" },
  { to: "/meals", icon: "🥗", label: "Meals" },
  { to: "/meal-suggestions", icon: "🍲", label: "Food Ideas" },
  { to: "/workouts", icon: "🏋️", label: "Workouts" },
  { to: "/water", icon: "💧", label: "Water" },
  { to: "/progress", icon: "📈", label: "Progress" },
  { to: "/scanner", icon: "🔍", label: "Food Scanner" },
  { to: "/settings", icon: "⚙️", label: "Settings" },
  { to: "/profile", icon: "👤", label: "Profile" },
  { to: "/users", icon: "👥", label: "Users", adminOnly: true },
];

export default function Navbar() {
  const { user, logout, isAuthenticated } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const logoSrc = "/kenntyfit-logo.png";
  const isAdmin = user?.role === "ADMIN" || user?.role === "ROLE_ADMIN";
  const visibleLinks = useMemo(
    () => links.filter((link) => !link.adminOnly || isAdmin),
    [isAdmin]
  );

  useEffect(() => {
    setMenuOpen(false);
  }, [location.pathname]);

  if (!isAuthenticated) return null;

  const handleLogout = () => {
    logout();
    navigate("/login");
    setMenuOpen(false);
  };

  const handleNavigate = (to) => {
    navigate(to);
    setMenuOpen(false);
  };

  return (
    <header className="app-header">
      <div className="app-header__top">
        <div className="app-brand">
          <img className="app-brand__icon" src={logoSrc} alt="KenntyFit logo" />
          <div className="app-brand__text">
            <div className="app-brand__name">KenntyFit</div>
            <div className="app-brand__sub">{user?.username || "Account"}</div>
          </div>
        </div>

        <button
          type="button"
          className="app-menu-button"
          aria-label="Open navigation menu"
          aria-expanded={menuOpen}
          aria-controls="app-nav-drawer"
          onClick={() => setMenuOpen((current) => !current)}
        >
          <span className="app-menu-button__bar" />
          <span className="app-menu-button__bar" />
          <span className="app-menu-button__bar" />
        </button>
      </div>

      {menuOpen ? <div className="app-nav-backdrop" onClick={() => setMenuOpen(false)} aria-hidden="true" /> : null}

      <aside className={`app-nav-drawer${menuOpen ? " open" : ""}`} id="app-nav-drawer" aria-label="Main navigation">
        <div className="app-nav-drawer__header">
          <div>
            <div className="app-nav-drawer__title">Menu</div>
            <div className="app-nav-drawer__subtitle">{user?.username || "Account"}</div>
          </div>
          <button
            type="button"
            className="app-nav-drawer__close"
            aria-label="Close navigation menu"
            onClick={() => setMenuOpen(false)}
          >
            ×
          </button>
        </div>

        <nav className="app-nav-drawer__links">
          {visibleLinks.map((link) => (
            <NavLink
              key={link.to}
              to={link.to}
              className={({ isActive }) => `app-nav-drawer__link${isActive ? " active" : ""}`}
              onClick={() => setMenuOpen(false)}
            >
              <span className="app-nav-drawer__icon">{link.icon}</span>
              <span className="app-nav-drawer__label">{link.label}</span>
            </NavLink>
          ))}
        </nav>

        <div className="app-nav-drawer__footer">
          <button type="button" className="btn btn-ghost app-nav-drawer__action" onClick={() => handleNavigate("/profile")}>
            Profile
          </button>
          <button type="button" className="btn btn-danger app-nav-drawer__action" onClick={handleLogout}>
            Sign Out
          </button>
        </div>
      </aside>
    </header>
  );
}
