import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import API from "../api/axios";

export default function Payment() {
  const { user }   = useAuth();
  const navigate   = useNavigate();
  const location   = useLocation();
  const plan       = location.state?.plan;
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState("");

  useEffect(() => {
    if (!plan) {
      navigate("/pricing");
    }
  }, [plan, navigate]);

  const handlePay = async () => {
    if (!plan || !user?.id) return;
    setError("");
    setLoading(true);

    try {
      const callbackUrl = `${window.location.origin}/payment-success`;
      const response = await API.post("/subscriptions/initialize", {
        userId: user.id,
        plan: plan.id.toUpperCase(),
        callbackUrl,
      });

      const { authorizationUrl, reference } = response.data;
      sessionStorage.setItem("pendingPayment", JSON.stringify({
        userId: user.id,
        plan: plan.id.toUpperCase(),
        reference
      }));

      window.location.assign(authorizationUrl);
    } catch (err) {
      console.error("Payment setup error:", err);
      setError(err.response?.data?.message || err.response?.data || err.message || "Failed to open payment. Try again.");
      setLoading(false);
    }
  };

  if (!plan) return null;

  return (
    <div style={{ minHeight:"100vh", background:"var(--bg)", display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
      <div style={{ width:"100%", maxWidth:460 }}>
        <button onClick={() => navigate("/pricing")} className="btn btn-ghost" style={{ marginBottom:20, fontSize:13 }}>← Back to Plans</button>
        <div className="card">
          <div style={{ textAlign:"center", paddingBottom:20, borderBottom:"1px solid var(--border)", marginBottom:20 }}>
            <div style={{ fontSize:36, marginBottom:10 }}>💳</div>
            <h1 style={{ fontFamily:"var(--font-display)", fontSize:22, fontWeight:800, marginBottom:6, color:"var(--text)" }}>Complete Payment</h1>
            <p style={{ color:"var(--muted)", fontSize:13 }}>Subscribing to the <strong style={{ color:"var(--accent2)" }}>{plan.name}</strong> plan</p>
          </div>
          <div style={{ marginBottom:20 }}>
            {[["Plan", plan.name],["Duration", plan.period],["Amount", `₦${plan.price.toLocaleString()}`]].map(([k,v]) => (
              <div key={k} style={{ display:"flex", justifyContent:"space-between", marginBottom:10, fontSize:14 }}>
                <span style={{ color:"var(--muted)" }}>{k}</span>
                <strong style={{ color: k==="Amount"?"var(--accent2)":"var(--text)", fontSize: k==="Amount"?18:14 }}>{v}</strong>
              </div>
            ))}
          </div>
          {error && <div className="alert alert-error" style={{ marginBottom:14 }}>⚠️ {error}</div>}
          <button onClick={handlePay} disabled={loading} className="btn btn-primary" style={{ width:"100%", padding:13, fontSize:15, borderRadius:10 }}>
            {loading ? "Opening checkout..." : `Pay ₦${plan.price.toLocaleString()} with Paystack →`}
          </button>
          <p style={{ textAlign:"center", marginTop:14, fontSize:11, color:"var(--muted)" }}>🔒 Secured by Paystack · You will be redirected to the hosted checkout</p>
        </div>
      </div>
    </div>
  );
}
