import React, { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const GENDERS = ["MALE", "FEMALE", "OTHER"];
const GOALS = ["WEIGHT_LOSS", "MUSCLE_GAIN", "MAINTAIN_WEIGHT", "IMPROVE_FITNESS"];
const ACTS = ["SEDENTARY", "LIGHTLY_ACTIVE", "MODERATELY_ACTIVE", "VERY_ACTIVE", "EXTRA_ACTIVE"];

const makeInitialForm = () => ({
  username: "",
  email: "",
  password: "",
  firstName: "",
  lastName: "",
  age: "",
  weight: "",
  height: "",
  gender: "MALE",
  fitnessGoal: "WEIGHT_LOSS",
  activityLevel: "MODERATELY_ACTIVE",
  dailyCalorieTarget: "2000",
  dailyWaterTarget: "2500",
  resetToken: "",
  newPassword: "",
  confirmPassword: ""
});

const getMessage = (value, fallback) => {
  if (typeof value === "string" && value.trim()) return value;
  if (value && typeof value === "object" && typeof value.message === "string") return value.message;
  return fallback;
};

const getErrorMessage = (err, fallback) => {
  const data = err?.response?.data;
  if (typeof data === "string" && data.trim()) return data;
  if (data && typeof data === "object") {
    if (typeof data.message === "string" && data.message.trim()) return data.message;
    if (typeof data.error === "string" && data.error.trim()) return data.error;
    if (typeof data.detail === "string" && data.detail.trim()) return data.detail;
    if (typeof data.status === "string" && data.status.trim()) return data.status;
  }

  if (err?.message === "Network Error") {
    return "Cannot reach the backend from this device. Check the API URL, phone network, and Windows Firewall.";
  }

  if (err?.response?.status) {
    return `Request failed with status ${err.response.status}.`;
  }

  return fallback;
};

export default function Login() {
  const { login, register, verifyOtp, resendOtp, forgotPassword, resetPassword } = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const logoSrc = "/kenntyfit-logo.png";
  const [mode, setMode] = useState(searchParams.get("mode") === "reset" || searchParams.get("token") ? "reset" : "login");
  const [otpMode, setOtpMode] = useState(false);
  const [form, setForm] = useState(makeInitialForm);
  const [otp, setOtp] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const token = searchParams.get("token");
    const routeMode = searchParams.get("mode");

    if (routeMode === "reset" || token) {
      setMode("reset");
      setOtpMode(false);
      setForm((current) => ({
        ...current,
        resetToken: token || current.resetToken
      }));
    }
  }, [searchParams]);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const openMode = (nextMode) => {
    setMode(nextMode);
    setOtpMode(false);
    setError("");
    setSuccess("");
    setOtp("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setLoading(true);

    try {
      if (mode === "login") {
        if (!otpMode) {
          const response = await login(form.username, form.password);
          if (response?.otpRequired) {
            setOtpMode(true);
            setSuccess(response.message || `OTP sent to ${response.maskedEmail || "your email"}.`);
            return;
          }
          navigate("/dashboard");
          return;
        }

        await verifyOtp(form.username, otp);
        navigate("/dashboard");
        return;
      }

      if (mode === "register") {
        await register(form.username, form.email, form.password, form);
        setSuccess("Account created. Check your email for confirmation, then sign in to receive your OTP.");
        setMode("login");
        setOtpMode(false);
        setOtp("");
        setForm(makeInitialForm());
        return;
      }

      if (mode === "forgot") {
        const response = await forgotPassword(form.email);
        setSuccess(getMessage(response, "Password reset email sent. Check your inbox."));
        return;
      }

      if (mode === "reset") {
        const response = await resetPassword(form.resetToken, form.newPassword, form.confirmPassword);
        setSuccess(getMessage(response, "Password reset successfully. You can sign in now."));
        setForm(makeInitialForm());
        setMode("login");
        setOtpMode(false);
        navigate("/login", { replace: true });
      }
    } catch (err) {
      setError(getErrorMessage(err, "Something went wrong."));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "var(--bg)", padding: 20 }}>
      <div style={{ position: "fixed", top: -200, right: -200, width: 600, height: 600, borderRadius: "50%", background: "radial-gradient(circle, rgba(0,229,160,0.05) 0%, transparent 70%)", pointerEvents: "none" }} />
      <div style={{ width: "100%", maxWidth: 420 }} className="fade-up">
        <div style={{ textAlign: "center", marginBottom: 36 }}>
          <img
            src={logoSrc}
            alt="KenntyFit logo"
            style={{ width: 64, height: 64, borderRadius: 18, objectFit: "cover", display: "inline-block", marginBottom: 14, background: "#0b1220" }}
          />
          <h1 style={{ fontFamily: "var(--font-display)", fontSize: 28, fontWeight: 800, letterSpacing: "-0.02em", color: "var(--text)" }}>KenntyFit</h1>
          <p style={{ color: "var(--muted)", fontSize: 13, marginTop: 6 }}>
            {mode === "login"
              ? "Welcome back. Sign in to continue."
              : mode === "register"
                ? "Create your account to get started."
                : mode === "forgot"
                  ? "Request a password reset email."
                  : "Use your reset token to set a new password."}
          </p>
        </div>
        <div className="card">
          {error && <div className="alert alert-error" style={{ marginBottom: 16 }}>⚠️ {error}</div>}
          {success && <div className="alert alert-success" style={{ marginBottom: 16 }}>✅ {success}</div>}
          <form onSubmit={handleSubmit}>
            {mode === "register" ? (
              <>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">Username</label>
                    <input className="input" type="text" placeholder="your_username" value={form.username} onChange={set("username")} required />
                  </div>
                  <div className="form-group">
                    <label className="label">Email</label>
                    <input className="input" type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} required />
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">First Name</label>
                    <input className="input" type="text" value={form.firstName} onChange={set("firstName")} required />
                  </div>
                  <div className="form-group">
                    <label className="label">Last Name</label>
                    <input className="input" type="text" value={form.lastName} onChange={set("lastName")} required />
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">Age</label>
                    <input className="input" type="number" value={form.age} onChange={set("age")} required />
                  </div>
                  <div className="form-group">
                    <label className="label">Gender</label>
                    <select className="input" value={form.gender} onChange={set("gender")} required>
                      {GENDERS.map((g) => <option key={g}>{g}</option>)}
                    </select>
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">Weight (kg)</label>
                    <input className="input" type="number" step="0.1" value={form.weight} onChange={set("weight")} required />
                  </div>
                  <div className="form-group">
                    <label className="label">Height (m)</label>
                    <input className="input" type="number" step="0.01" value={form.height} onChange={set("height")} required />
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">Fitness Goal</label>
                    <select className="input" value={form.fitnessGoal} onChange={set("fitnessGoal")} required>
                      {GOALS.map((g) => <option key={g}>{g}</option>)}
                    </select>
                  </div>
                  <div className="form-group">
                    <label className="label">Activity Level</label>
                    <select className="input" value={form.activityLevel} onChange={set("activityLevel")} required>
                      {ACTS.map((a) => <option key={a}>{a}</option>)}
                    </select>
                  </div>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 14 }}>
                  <div className="form-group">
                    <label className="label">Daily Calorie Target</label>
                    <input className="input" type="number" value={form.dailyCalorieTarget} onChange={set("dailyCalorieTarget")} placeholder="2000" required />
                  </div>
                  <div className="form-group">
                    <label className="label">Daily Water Target (ml)</label>
                    <input className="input" type="number" value={form.dailyWaterTarget} onChange={set("dailyWaterTarget")} placeholder="2500" required />
                  </div>
                </div>
                <div className="form-group" style={{ marginBottom: 22 }}>
                  <label className="label">Password</label>
                  <input className="input" type="password" placeholder="••••••••" value={form.password} onChange={set("password")} required />
                </div>
              </>
            ) : mode === "forgot" ? (
              <>
                <div className="form-group" style={{ marginBottom: 22 }}>
                  <label className="label">Email</label>
                  <input className="input" type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} required />
                </div>
              </>
            ) : mode === "reset" ? (
              <>
                <div className="form-group" style={{ marginBottom: 14 }}>
                  <label className="label">Reset Token</label>
                  <input className="input" type="text" placeholder="Paste token from email" value={form.resetToken} onChange={set("resetToken")} required />
                </div>
                <div className="form-group" style={{ marginBottom: 14 }}>
                  <label className="label">New Password</label>
                  <input className="input" type="password" placeholder="New password" value={form.newPassword} onChange={set("newPassword")} required />
                </div>
                <div className="form-group" style={{ marginBottom: 22 }}>
                  <label className="label">Confirm Password</label>
                  <input className="input" type="password" placeholder="Confirm new password" value={form.confirmPassword} onChange={set("confirmPassword")} required />
                </div>
              </>
            ) : (
              <>
                <div className="form-group" style={{ marginBottom: 14 }}>
                  <label className="label">Username</label>
                  <input className="input" type="text" placeholder="your_username" value={form.username} onChange={set("username")} required />
                </div>
                <div className="form-group" style={{ marginBottom: 22 }}>
                  <label className="label">Password</label>
                  <input className="input" type="password" placeholder="••••••••" value={form.password} onChange={set("password")} required />
                </div>
                {otpMode && (
                  <div className="form-group" style={{ marginBottom: 22 }}>
                    <label className="label">OTP Code</label>
                    <input className="input" type="text" inputMode="numeric" maxLength={6} placeholder="Enter 6-digit OTP" value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))} required />
                    <div style={{ marginTop: 8, fontSize: 12, color: "var(--muted)" }}>
                      We sent the code to your email. Enter it to complete sign in.
                    </div>
                  </div>
                )}
              </>
            )}

            <button type="submit" className="btn btn-primary" style={{ width: "100%", padding: 13, fontSize: 15 }} disabled={loading}>
              {loading
                ? "Please wait..."
                : mode === "login"
                  ? (otpMode ? "Verify OTP ->" : "Sign In ->")
                  : mode === "register"
                    ? "Create Account ->"
                    : mode === "forgot"
                      ? "Send Reset Email ->"
                      : "Reset Password ->"}
            </button>
          </form>

          {mode === "login" && otpMode && (
            <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
              <button
                type="button"
                className="btn btn-ghost"
                style={{ flex: 1, padding: 12, fontSize: 13 }}
                disabled={loading}
                onClick={async () => {
                    try {
                      setLoading(true);
                      setError("");
                      const response = await resendOtp(form.username, form.password);
                      setSuccess(response.message || "OTP resent. Check your email.");
                    } catch (err) {
                      setError(getErrorMessage(err, "Could not resend OTP."));
                    } finally {
                      setLoading(false);
                    }
                  }}
              >
                Resend OTP
              </button>
              <button
                type="button"
                className="btn btn-ghost"
                style={{ flex: 1, padding: 12, fontSize: 13 }}
                onClick={() => {
                  setOtpMode(false);
                  setOtp("");
                }}
              >
                Back
              </button>
            </div>
          )}

          <div style={{ marginTop: 18, display: "flex", flexWrap: "wrap", gap: 10, justifyContent: "center" }}>
            {mode !== "login" && (
              <button
                type="button"
                className="btn btn-ghost"
                style={{ padding: "10px 12px", fontSize: 13 }}
                onClick={() => openMode("login")}
              >
                Back to sign in
              </button>
            )}
            {mode !== "register" && (
              <button
                type="button"
                className="btn btn-ghost"
                style={{ padding: "10px 12px", fontSize: 13 }}
                onClick={() => openMode("register")}
              >
                Create account
              </button>
            )}
            {mode === "login" && (
              <button
                type="button"
                className="btn btn-ghost"
                style={{ padding: "10px 12px", fontSize: 13 }}
                onClick={() => openMode("forgot")}
              >
                Forgot password
              </button>
            )}
            {mode === "forgot" && (
              <button
                type="button"
                className="btn btn-ghost"
                style={{ padding: "10px 12px", fontSize: 13 }}
                onClick={() => openMode("reset")}
              >
                I have a reset token
              </button>
            )}
            {mode === "reset" && (
              <button
                type="button"
                className="btn btn-ghost"
                style={{ padding: "10px 12px", fontSize: 13 }}
                onClick={() => openMode("forgot")}
              >
                Request reset email
              </button>
            )}
          </div>

          {mode === "login" && (
            <div style={{ marginTop: 20, padding: 12, background: "rgba(0,153,255,0.08)", borderRadius: 8, fontSize: 12, color: "var(--accent2)" }}>
              Sign in with your username and password, then enter the OTP sent to your email.
            </div>
          )}
          {mode === "forgot" && (
            <div style={{ marginTop: 20, padding: 12, background: "rgba(0,153,255,0.08)", borderRadius: 8, fontSize: 12, color: "var(--accent2)" }}>
              We will email you a reset token and a direct reset link.
            </div>
          )}
          {mode === "reset" && (
            <div style={{ marginTop: 20, padding: 12, background: "rgba(0,153,255,0.08)", borderRadius: 8, fontSize: 12, color: "var(--accent2)" }}>
              Use the token from your email or the link we sent to set a new password.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
