import React, { useEffect, useMemo, useState } from "react";
import { Capacitor } from "@capacitor/core";
import API from "../api/axios";
import { useAuth } from "../context/AuthContext";
import { HYDRATION_EVENTS } from "../services/hydrationAutoTracker";

const formatSourceLabel = (sourceDevice) => {
  if (!sourceDevice) return "device";
  return String(sourceDevice).replaceAll("_", " ").toLowerCase();
};

export default function HydrationConfirmationPrompt() {
  const { user } = useAuth();
  const [pendingDetection, setPendingDetection] = useState(null);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");

  const activeDetection = useMemo(() => {
    if (!pendingDetection) return null;
    if (user?.id && String(user.id) !== String(pendingDetection.userId)) {
      return null;
    }
    return pendingDetection;
  }, [pendingDetection, user?.id]);

  useEffect(() => {
    const handleDetected = (event) => {
      if (!user?.id) return;
      const detail = event?.detail || {};
      if (String(detail.userId) !== String(user.id)) return;
      setMessage("");
      setPendingDetection(detail);
    };

    window.addEventListener(HYDRATION_EVENTS.DETECTED, handleDetected);
    return () => window.removeEventListener(HYDRATION_EVENTS.DETECTED, handleDetected);
  }, [user?.id]);

  const dismiss = () => {
    setPendingDetection(null);
    setMessage("");
  };

  const confirmWater = async () => {
    if (!activeDetection || !user?.id) return;

    setSaving(true);
    setMessage("");

    try {
      await API.post(`/water-intake/user/${user.id}/auto-track`, {
        amountMl: activeDetection.amountMl,
        deviceWithUser: true,
        sourceDevice: activeDetection.sourceDevice || "PHONE",
        sensorType: activeDetection.sensorType || "MOTION_PATTERN",
        beverageType: "WATER",
        sourceReference: "AUTO_ON_BODY_MOTION_CONFIRMED",
        source: activeDetection.sourceDevice || "PHONE",
        confidenceScore: activeDetection.confidenceScore,
        sipCount: activeDetection.sipCount,
        detectedAt: activeDetection.detectedAt,
        notes: `Confirmed as water on ${Capacitor.getPlatform()} after liquid detection.`,
      });

      window.dispatchEvent(new CustomEvent(HYDRATION_EVENTS.CONFIRMED));
      setMessage("Water recorded.");
      setPendingDetection(null);
    } catch (error) {
      console.warn("Failed to save hydration confirmation:", error);
      setMessage(error.response?.data?.message || "Could not save the water record.");
    } finally {
      setSaving(false);
    }
  };

  if (!activeDetection) {
    return null;
  }

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 2000,
        background: "rgba(5, 7, 13, 0.72)",
        backdropFilter: "blur(6px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 20,
      }}
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Hydration confirmation"
        style={{
          width: "min(420px, 100%)",
          background: "var(--card)",
          border: "1px solid var(--border)",
          borderRadius: 18,
          padding: 22,
          boxShadow: "0 18px 40px rgba(0,0,0,0.35)",
        }}
      >
        <div style={{ fontSize: 12, color: "var(--muted)", textTransform: "uppercase", letterSpacing: 0.08, marginBottom: 8 }}>
          Liquid detected
        </div>
        <h3 style={{ margin: 0, fontSize: 20, fontWeight: 800, color: "var(--text)" }}>Are you drinking water?</h3>
        <p style={{ margin: "10px 0 0 0", color: "var(--muted)", fontSize: 13, lineHeight: 1.6 }}>
          The app detected a drinking pattern on your {formatSourceLabel(activeDetection.sourceDevice)}.
          If it is water, confirm it and the app will record it. If it is not water, it will not be saved.
        </p>

        <div style={{ marginTop: 16, display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 10 }}>
          <button className="btn btn-primary" disabled={saving} onClick={confirmWater}>
            {saving ? "Saving..." : "It is water"}
          </button>
          <button
            className="btn"
            disabled={saving}
            onClick={dismiss}
            style={{ border: "1px solid var(--border)", background: "var(--bg2)", color: "var(--text)" }}
          >
            Not water
          </button>
        </div>

        {message && (
          <div style={{ marginTop: 12, fontSize: 12, color: "var(--muted)" }}>
            {message}
          </div>
        )}
      </div>
    </div>
  );
}
