import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider, useAuth } from "./context/AuthContext";
import ErrorBoundary from "./components/ErrorBoundary";
import ProtectedRoute from "./components/ProtectedRoute";
import SubscriptionGuard from "./components/SubscriptionGuard";
import Navbar from "./components/Navbar";
import AutoHydrationTracker from "./components/AutoHydrationTracker";
import HydrationConfirmationPrompt from "./components/HydrationConfirmationPrompt";
import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Meals from "./pages/Meals";
import MealSuggestions from "./pages/MealSuggestions";
import Workouts from "./pages/Workouts";
import Water from "./pages/Water";
import Progress from "./pages/Progress";
import FoodScanner from "./pages/FoodScanner";
import Users from "./pages/Users";
import Pricing from "./pages/Pricing";
import Payment from "./pages/Payment";
import PaymentSuccess from "./pages/PaymentSuccess";
import Profile from "./pages/Profile";
import Settings from "./pages/Settings";
import Welcome from "./pages/Welcome";
import "./App.css";

const G = ({ children }) => (
  <ProtectedRoute>
    <SubscriptionGuard>{children}</SubscriptionGuard>
  </ProtectedRoute>
);

function AppShell() {
  const { user } = useAuth();
  const PublicAuthRoute = ({ children }) => (user ? <Navigate to="/dashboard" replace /> : children);

  return (
    <Router>
      <AutoHydrationTracker />
      <HydrationConfirmationPrompt />
      <div className="app-wrapper">
        <Navbar />
        <main className="main-content">
          <Routes>
            <Route path="/login" element={<PublicAuthRoute><Login /></PublicAuthRoute>} />
            <Route path="/welcome" element={<Welcome />} />
            <Route path="/pricing" element={<ProtectedRoute><Pricing /></ProtectedRoute>} />
            <Route path="/payment" element={<ProtectedRoute><Payment /></ProtectedRoute>} />
            <Route path="/payment-success" element={<ProtectedRoute><PaymentSuccess /></ProtectedRoute>} />
            <Route path="/dashboard" element={<G><Dashboard /></G>} />
            <Route path="/meals" element={<G><Meals /></G>} />
            <Route path="/meal-suggestions" element={<G><MealSuggestions /></G>} />
            <Route path="/workouts" element={<G><Workouts /></G>} />
            <Route path="/water" element={<G><Water /></G>} />
            <Route path="/progress" element={<G><Progress /></G>} />
            <Route path="/scanner" element={<G><FoodScanner /></G>} />
            <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
            <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
            <Route path="/users" element={<ProtectedRoute adminOnly><Users /></ProtectedRoute>} />
            <Route path="/" element={<Welcome />} />
            <Route path="*" element={<Welcome />} />
          </Routes>
        </main>
      </div>
    </Router>
  );
}

export default function App() {
  return (
    <ErrorBoundary>
      <AuthProvider>
        <AppShell />
      </AuthProvider>
    </ErrorBoundary>
  );
}
