import { Device } from "@capacitor/device";
import { Motion } from "@capacitor/motion";

const COOLDOWN_MS = 10 * 60 * 1000;
const SAMPLE_WINDOW_MS = 5000;
const PEAK_THRESHOLD = 1.6;
const MIN_PEAKS_FOR_DETECTION = 3;
const HYDRATION_DETECTED_EVENT = "hydrationDetected";

let trackerState = {
  active: false,
  userId: null,
  sourceDevice: "PHONE",
  lastDetectionAt: 0,
  samples: [],
  subscription: null,
};

const now = () => Date.now();

const isNativeDevice = async () => {
  try {
    const info = await Device.getInfo();
    return info.platform !== "web";
  } catch (error) {
    return false;
  }
};

const getMagnitude = (acceleration = {}) => {
  const x = Number(acceleration.x || 0);
  const y = Number(acceleration.y || 0);
  const z = Number(acceleration.z || 0);
  return Math.sqrt(x * x + y * y + z * z);
};

const pruneSamples = (samples) => {
  const cutoff = now() - SAMPLE_WINDOW_MS;
  return samples.filter((sample) => sample.timestamp >= cutoff);
};

const scoreSamples = (samples) => {
  const peaks = samples.filter((sample) => sample.magnitude >= PEAK_THRESHOLD);
  return {
    peakCount: peaks.length,
    peakStrength: peaks.reduce((sum, sample) => sum + sample.magnitude, 0),
  };
};

const estimateAmountMl = (peakCount, peakStrength) => {
  const base = 180;
  const intensityBonus = Math.min(120, Math.round((peakStrength - peakCount) * 25));
  const sipBonus = Math.min(100, Math.max(0, peakCount - MIN_PEAKS_FOR_DETECTION) * 20);
  return Math.max(120, Math.min(400, base + intensityBonus + sipBonus));
};

const shouldDetectDrink = (samples) => {
  const { peakCount, peakStrength } = scoreSamples(samples);
  const firstPeak = samples.find((sample) => sample.magnitude >= PEAK_THRESHOLD);
  const lastPeak = [...samples].reverse().find((sample) => sample.magnitude >= PEAK_THRESHOLD);

  if (!firstPeak || !lastPeak) {
    return null;
  }

  const spanMs = lastPeak.timestamp - firstPeak.timestamp;
  if (peakCount < MIN_PEAKS_FOR_DETECTION || spanMs > SAMPLE_WINDOW_MS) {
    return null;
  }

  return {
    amountMl: estimateAmountMl(peakCount, peakStrength),
    confidenceScore: Math.min(0.95, 0.55 + peakCount * 0.08),
    sipCount: peakCount,
  };
};

const emitDetection = (detection) => {
  window.dispatchEvent(
    new CustomEvent(HYDRATION_DETECTED_EVENT, {
      detail: {
        userId: trackerState.userId,
        sourceDevice: trackerState.sourceDevice,
        amountMl: detection.amountMl,
        confidenceScore: detection.confidenceScore,
        sipCount: detection.sipCount,
        sensorType: "MOTION_PATTERN",
        detectedAt: new Date().toISOString(),
      },
    })
  );
};

const processSample = async (sample) => {
  if (!trackerState.active || !trackerState.userId) return;

  trackerState.samples.push(sample);
  trackerState.samples = pruneSamples(trackerState.samples);

  if (now() - trackerState.lastDetectionAt < COOLDOWN_MS) {
    return;
  }

  const detection = shouldDetectDrink(trackerState.samples);
  if (!detection) {
    return;
  }

  trackerState.lastDetectionAt = now();
  trackerState.samples = [];

  try {
    emitDetection(detection);
  } catch (error) {
    console.warn("Failed to emit hydration detection:", error);
  }
};

export const startHydrationAutoTracking = async ({ userId, sourceDevice = "PHONE" }) => {
  if (!userId || !(await isNativeDevice())) {
    return null;
  }

  await stopHydrationAutoTracking();

  trackerState = {
    active: true,
    userId,
    sourceDevice,
    lastDetectionAt: 0,
    samples: [],
    subscription: null,
  };

  try {
    trackerState.subscription = await Motion.addListener("accel", (event) => {
      void processSample({
        timestamp: now(),
        magnitude: getMagnitude(event?.acceleration),
      });
    });

    return trackerState.subscription;
  } catch (error) {
    trackerState.active = false;
    trackerState.userId = null;
    trackerState.samples = [];
    console.warn("Hydration auto-tracking is unavailable:", error);
    return null;
  }
};

export const stopHydrationAutoTracking = async () => {
  if (trackerState.subscription?.remove) {
    try {
      await trackerState.subscription.remove();
    } catch (error) {
      // Ignore cleanup errors.
    }
  }

  trackerState = {
    active: false,
    userId: null,
    sourceDevice: "PHONE",
    lastDetectionAt: 0,
    samples: [],
    subscription: null,
  };
};

export const getHydrationAutoTrackerState = () => ({
  active: trackerState.active,
  userId: trackerState.userId,
  sourceDevice: trackerState.sourceDevice,
  lastDetectionAt: trackerState.lastDetectionAt,
});

export const HYDRATION_EVENTS = {
  DETECTED: HYDRATION_DETECTED_EVENT,
  CONFIRMED: "hydrationAutoTracked",
};
