import React, { useCallback, useEffect, useMemo, useState } from "react";
import { XAxis, YAxis, Tooltip, ResponsiveContainer, BarChart, Bar } from "recharts";
import API from "../api/axios";
import { useAuth } from "../context/AuthContext";

const toDateKey = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const getGoalStatus = (current, target) => {
  const percentage = target > 0 ? (current / target) * 100 : 0;
  if (percentage >= 100) return { text: "Exceeded", color: "var(--accent)" };
  if (percentage >= 75) return { text: "Great", color: "var(--accent)" };
  if (percentage >= 50) return { text: "Good", color: "var(--accent2)" };
  return { text: "Working", color: "var(--accent3)" };
};

export default function Progress() {
  const { user } = useAuth();
  const [timeRange, setTimeRange] = useState("week");
  const [summary, setSummary] = useState(null);
  const [chartData, setChartData] = useState([]);
  const [todayWorkoutSummary, setTodayWorkoutSummary] = useState(null);
  const [todayWaterStatus, setTodayWaterStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadProgressData = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");

    const summaryPath = timeRange === "week" ? "weekly-summary" : "monthly-summary";

    try {
      const [summaryRes, workoutSummaryRes, waterStatusRes] = await Promise.allSettled([
        API.get(`/progress/user/${user.id}/${summaryPath}`),
        API.get(`/workouts/user/${user.id}/summary`),
        API.get(`/water-intake/user/${user.id}/status`),
      ]);

      const summaryData = summaryRes.status === "fulfilled" ? summaryRes.value.data || null : null;
      setSummary(summaryData);
      setTodayWorkoutSummary(workoutSummaryRes.status === "fulfilled" ? workoutSummaryRes.value.data || null : null);
      setTodayWaterStatus(waterStatusRes.status === "fulfilled" ? waterStatusRes.value.data || null : null);

      const failures = [];
      if (summaryRes.status === "rejected") failures.push("progress summary");
      if (workoutSummaryRes.status === "rejected") failures.push("workout summary");
      if (waterStatusRes.status === "rejected") failures.push("water status");

      if (summaryData?.startDate && summaryData?.endDate) {
        const workoutsRangeRes = await Promise.allSettled([
          API.get(`/workouts/user/${user.id}/date-range`, {
            params: {
              startDate: summaryData.startDate,
              endDate: summaryData.endDate,
            },
          }),
        ]);

        const workoutsRange = workoutsRangeRes[0];
        if (workoutsRange.status === "fulfilled") {
          const workouts = Array.isArray(workoutsRange.value.data) ? workoutsRange.value.data : [];
          const grouped = new Map();

          const startDate = new Date(summaryData.startDate);
          const endDate = new Date(summaryData.endDate);
          for (let cursor = new Date(startDate); cursor <= endDate; cursor.setDate(cursor.getDate() + 1)) {
            const key = toDateKey(cursor);
            grouped.set(key, {
              label:
                timeRange === "week"
                  ? cursor.toLocaleDateString("en-NG", { weekday: "short" })
                  : String(cursor.getDate()).padStart(2, "0"),
              steps: 0,
            });
          }

          workouts.forEach((workout) => {
            if (!workout?.workoutDate || !grouped.has(workout.workoutDate)) return;
            grouped.get(workout.workoutDate).steps += Number(workout.stepCount || 0);
          });

          setChartData(Array.from(grouped.values()));
        } else {
          failures.push("step chart");
          setChartData([]);
        }
      } else {
        setChartData([]);
      }
      if (failures.length > 0) {
        setError(`Some progress sections could not load: ${failures.join(", ")}.`);
      }
    } catch (err) {
      console.error("Failed to load progress data:", err);
      setError(err.response?.data?.message || "Could not load progress analytics.");
      setSummary(null);
      setChartData([]);
      setTodayWorkoutSummary(null);
      setTodayWaterStatus(null);
    } finally {
      setLoading(false);
    }
  }, [timeRange, user?.id]);

  useEffect(() => {
    loadProgressData();
  }, [loadProgressData]);

  const stepGoal = useMemo(() => {
    if (timeRange === "week") return 70000;
    const totalDays = chartData.length || 30;
    return totalDays * 10000;
  }, [chartData.length, timeRange]);

  const waterGoal = useMemo(() => {
    const dailyTarget = user?.dailyWaterTarget || 2500;
    if (timeRange === "week") return dailyTarget * 7;
    return dailyTarget * (chartData.length || 30);
  }, [chartData.length, timeRange, user?.dailyWaterTarget]);

  if (!user) {
    return <div className="loading">Please log in to view progress.</div>;
  }

  if (loading) {
    return <div className="loading">Loading progress...</div>;
  }

  return (
    <div className="page fade-up">
      <div style={{ marginBottom: 24 }}>
        <h1 className="page-title">Progress 📈</h1>
        <p className="page-sub">Backend activity analytics</p>
      </div>

      {error && (
        <div
          className="card"
          style={{ marginBottom: 24, border: "1px solid #f59e0b", background: "rgba(245, 158, 11, 0.08)" }}
        >
          {error}
        </div>
      )}

      <div style={{ display: "flex", gap: 6, marginBottom: 24 }}>
        {["week", "month"].map((range) => (
          <button
            key={range}
            onClick={() => setTimeRange(range)}
            className="btn"
            style={{
              padding: "8px 16px",
              fontSize: 12,
              fontWeight: timeRange === range ? 700 : 400,
              background: timeRange === range ? "var(--accent)" : "var(--card)",
              color: timeRange === range ? "#fff" : "var(--text)",
              border: "1px solid var(--border)",
              cursor: "pointer",
              borderRadius: 6,
            }}
          >
            {range === "week" ? "Weekly" : "Monthly"}
          </button>
        ))}
      </div>

      {(todayWorkoutSummary || todayWaterStatus) && (
        <div
          className="card"
          style={{ background: "linear-gradient(135deg, var(--accent) 0%, var(--accent2) 100%)", color: "#fff", marginBottom: 24 }}
        >
          <h3 style={{ margin: "0 0 16px 0", fontSize: 16, fontWeight: 700 }}>Today at a Glance</h3>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 16 }}>
            <div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", textTransform: "uppercase", marginBottom: 6 }}>Steps</div>
              <div style={{ fontSize: 28, fontWeight: 700 }}>{(todayWorkoutSummary?.totalSteps || 0).toLocaleString()}</div>
              <div style={{ fontSize: 12, color: "rgba(255,255,255,0.8)" }}>from logged workouts</div>
            </div>
            <div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", textTransform: "uppercase", marginBottom: 6 }}>Calories</div>
              <div style={{ fontSize: 28, fontWeight: 700 }}>{(todayWorkoutSummary?.totalCaloriesBurned || 0).toLocaleString()}</div>
              <div style={{ fontSize: 12, color: "rgba(255,255,255,0.8)" }}>burned today</div>
            </div>
            <div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", textTransform: "uppercase", marginBottom: 6 }}>Water</div>
              <div style={{ fontSize: 28, fontWeight: 700 }}>{(todayWaterStatus?.totalWaterMl || 0).toLocaleString()}</div>
              <div style={{ fontSize: 12, color: "rgba(255,255,255,0.8)" }}>ml tracked today</div>
            </div>
          </div>
        </div>
      )}

      {summary && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16, marginBottom: 24 }}>
          <div className="card">
            <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Total Steps</div>
            <div style={{ fontSize: 28, fontWeight: 700, color: "var(--accent)", marginBottom: 6 }}>{(summary.totalSteps || 0).toLocaleString()}</div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>{timeRange === "week" ? "this week" : "this month"}</div>
          </div>

          <div className="card">
            <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Daily Average Steps</div>
            <div style={{ fontSize: 28, fontWeight: 700, color: "var(--accent2)", marginBottom: 6 }}>
              {(summary.averageDailySteps || 0).toLocaleString()}
            </div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>per day</div>
          </div>

          <div className="card">
            <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Water Total</div>
            <div style={{ fontSize: 28, fontWeight: 700, color: "var(--accent3)", marginBottom: 6 }}>
              {(summary.waterTotalMl || 0).toLocaleString()}
            </div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>ml tracked in period</div>
          </div>

          <div className="card">
            <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Workouts Completed</div>
            <div style={{ fontSize: 28, fontWeight: 700, marginBottom: 6 }}>{(summary.workoutsCompleted || 0).toLocaleString()}</div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>{(summary.activeDays || 0).toLocaleString()} active days</div>
          </div>
        </div>
      )}

      {chartData.length > 0 && (
        <div className="card" style={{ marginBottom: 24 }}>
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 16, margin: "0 0 16px 0" }}>
            {timeRange === "week" ? "Weekly Step Breakdown" : "Monthly Step Breakdown"}
          </h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
              <XAxis dataKey="label" tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <Tooltip
                contentStyle={{
                  background: "var(--bg2)",
                  border: "1px solid var(--border)",
                  borderRadius: 8,
                  fontSize: 12,
                }}
                formatter={(value) => [Number(value).toLocaleString(), "Steps"]}
              />
              <Bar dataKey="steps" fill="var(--accent)" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {summary && (
        <div className="card" style={{ marginBottom: 24 }}>
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 16, margin: "0 0 16px 0" }}>Goals Status</h3>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {[
              { name: "Step Goal", target: stepGoal, current: summary.totalSteps || 0 },
              { name: "Water Goal", target: waterGoal, current: summary.waterTotalMl || 0 },
              { name: "Workout Minutes", target: timeRange === "week" ? 150 : 600, current: summary.totalWorkoutMinutes || 0 },
            ].map((goal) => {
              const status = getGoalStatus(goal.current, goal.target);
              const percentage = goal.target > 0 ? Math.round((goal.current / goal.target) * 100) : 0;

              return (
                <div key={goal.name} style={{ display: "flex", alignItems: "center", gap: 12 }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                      <span style={{ fontSize: 13, fontWeight: 600 }}>{goal.name}</span>
                      <span style={{ fontSize: 12, color: "var(--muted)" }}>
                        {goal.current.toLocaleString()} / {goal.target.toLocaleString()}
                      </span>
                    </div>
                    <div style={{ height: 8, background: "var(--border)", borderRadius: 4, overflow: "hidden" }}>
                      <div
                        style={{
                          height: "100%",
                          background: "var(--accent)",
                          width: `${Math.min(100, percentage)}%`,
                          transition: "width 0.3s ease",
                        }}
                      />
                    </div>
                  </div>
                  <div style={{ width: 72, textAlign: "right", fontSize: 12, fontWeight: 600, color: status.color }}>
                    {percentage}%
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {summary && (
        <div className="card" style={{ background: "var(--bg)" }}>
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, margin: "0 0 12px 0" }}>Insights</h3>
          <ul style={{ margin: 0, paddingLeft: 20, fontSize: 13, color: "var(--text)", lineHeight: 1.8 }}>
            <li>{summary.summary}</li>
            <li>
              Average daily water: <strong>{(summary.averageDailyWaterMl || 0).toLocaleString()} ml</strong>
            </li>
            <li>
              Calories burned: <strong>{(summary.totalCaloriesBurned || 0).toLocaleString()} kcal</strong>
            </li>
          </ul>
        </div>
      )}
    </div>
  );
}
