// ============================================================
// src/pages/Users.jsx  — ADMIN ONLY
// ============================================================
import React, { useEffect, useState } from "react";
import API from "../api/axios";

const EMPTY = { username:"",email:"",firstName:"",lastName:"",age:"",weight:"",height:"",gender:"MALE",fitnessGoal:"WEIGHT_LOSS",activityLevel:"MODERATELY_ACTIVE",dailyCalorieTarget:"",dailyWaterTarget:"",role:"USER" };
const GENDERS = ["MALE","FEMALE","OTHER"];
const GOALS   = ["WEIGHT_LOSS","MUSCLE_GAIN","MAINTAIN_WEIGHT","IMPROVE_FITNESS"];
const ACTS    = ["SEDENTARY","LIGHTLY_ACTIVE","MODERATELY_ACTIVE","VERY_ACTIVE","EXTRA_ACTIVE"];

export default function Users() {
  const [users,     setUsers]     = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editing,   setEditing]   = useState(null);
  const [form,      setForm]      = useState(EMPTY);
  const [error,     setError]     = useState("");
  const [search,    setSearch]    = useState("");

  const load = () => API.get("/users").then(r => { setUsers(r.data || []); setLoading(false); });
  useEffect(() => { load(); }, []);

  const set = k => e => setForm(f => ({ ...f, [k]: e.target.value }));
  const openAdd  = () => { setEditing(null); setForm(EMPTY); setError(""); setShowModal(true); };
  const openEdit = u => { setEditing(u.id); setForm({ ...u }); setError(""); setShowModal(true); };

  const handleSubmit = async (e) => {
    e.preventDefault(); setError("");
    try {
      const p = { ...form, age:+form.age, weight:+form.weight, height:+form.height, dailyCalorieTarget:+form.dailyCalorieTarget, dailyWaterTarget:+form.dailyWaterTarget };
      if (editing) await API.put(`/users/${editing}`, p);
      else         await API.post("/users", p);
      setShowModal(false); load();
    } catch (err) { setError(err.response?.data?.message || "Failed to save."); }
  };

  const del = async (id) => { if (!window.confirm("Delete this user?")) return; await API.delete(`/users/${id}`); load(); };

  const filtered = users.filter(u => u.username?.toLowerCase().includes(search.toLowerCase()) || u.email?.toLowerCase().includes(search.toLowerCase()));

  if (loading) return <div className="loading">Loading users...</div>;

  return (
    <div className="page fade-up">
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:24 }}>
        <div><h1 className="page-title">Users 👥</h1><p className="page-sub">{users.length} total users · Admin only</p></div>
        <button className="btn btn-primary" onClick={openAdd}>+ Add User</button>
      </div>
      <div style={{ marginBottom:18 }}><input className="input" style={{ maxWidth:340 }} placeholder="Search by username or email..." value={search} onChange={e => setSearch(e.target.value)} /></div>
      <div className="grid-3" style={{ marginBottom:20 }}>
        {[{ label:"Total Users", value:users.length, color:"var(--accent)", icon:"👥" },{ label:"Admins", value:users.filter(u=>u.role?.includes("ADMIN")).length, color:"var(--accent3)", icon:"🔑" },{ label:"Members", value:users.filter(u=>!u.role?.includes("ADMIN")).length, color:"var(--accent2)", icon:"🙋" }].map(s => (
          <div key={s.label} className="card" style={{ display:"flex", alignItems:"center", gap:14 }}>
            <span style={{ fontSize:26 }}>{s.icon}</span>
            <div>
              <div style={{ fontSize:11, color:"var(--muted)", textTransform:"uppercase", letterSpacing:"0.06em" }}>{s.label}</div>
              <div style={{ fontFamily:"var(--font-display)", fontSize:24, fontWeight:800, color:s.color }}>{s.value}</div>
            </div>
          </div>
        ))}
      </div>
      <div className="card" style={{ padding:0, overflow:"hidden" }}>
        <table className="table">
          <thead><tr><th>User</th><th>Email</th><th>Age</th><th>Goal</th><th>Role</th><th>Joined</th><th></th></tr></thead>
          <tbody>
            {filtered.length === 0 ? <tr><td colSpan={7} style={{ textAlign:"center", padding:40, color:"var(--muted)" }}>No users found.</td></tr>
            : filtered.map(u => (
              <tr key={u.id}>
                <td>
                  <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                    <div style={{ width:32, height:32, borderRadius:"50%", background:"var(--accent)", display:"flex", alignItems:"center", justifyContent:"center", fontWeight:700, fontSize:13, color:"#0a0e1a" }}>{u.username?.[0]?.toUpperCase()}</div>
                    <div><div style={{ fontWeight:600 }}>{u.username}</div><div style={{ fontSize:11, color:"var(--muted)" }}>{u.firstName} {u.lastName}</div></div>
                  </div>
                </td>
                <td style={{ color:"var(--muted)", fontSize:13 }}>{u.email}</td>
                <td>{u.age}</td>
                <td><span className="badge badge-blue" style={{ fontSize:10 }}>{u.fitnessGoal?.replace(/_/g," ")}</span></td>
                <td><span className={`badge ${u.role?.includes("ADMIN")?"badge-red":"badge-green"}`}>{u.role?.replace("ROLE_","")}</span></td>
                <td style={{ color:"var(--muted)", fontSize:12 }}>{u.createdAt?.split("T")[0]}</td>
                <td><div style={{ display:"flex", gap:6 }}>
                  <button className="btn btn-ghost" style={{ padding:"4px 10px", fontSize:11 }} onClick={() => openEdit(u)}>Edit</button>
                  <button className="btn btn-danger" style={{ padding:"4px 10px", fontSize:11 }} onClick={() => del(u.id)}>Del</button>
                </div></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2 className="modal-title">{editing ? "Edit User" : "Add New User"}</h2>
            {error && <div className="alert alert-error" style={{ marginBottom:14 }}>{error}</div>}
            <form onSubmit={handleSubmit}>
              <div className="form-grid">
                <div className="form-group"><label className="label">Username</label><input className="input" value={form.username} onChange={set("username")} required /></div>
                <div className="form-group"><label className="label">Email</label><input className="input" type="email" value={form.email} onChange={set("email")} /></div>
                <div className="form-group"><label className="label">First Name</label><input className="input" value={form.firstName} onChange={set("firstName")} /></div>
                <div className="form-group"><label className="label">Last Name</label><input className="input" value={form.lastName} onChange={set("lastName")} /></div>
                <div className="form-group"><label className="label">Age</label><input className="input" type="number" value={form.age} onChange={set("age")} /></div>
                <div className="form-group"><label className="label">Gender</label><select className="input" value={form.gender} onChange={set("gender")}>{GENDERS.map(g => <option key={g}>{g}</option>)}</select></div>
                <div className="form-group"><label className="label">Weight (kg)</label><input className="input" type="number" step="0.1" value={form.weight} onChange={set("weight")} /></div>
                <div className="form-group"><label className="label">Height (m)</label><input className="input" type="number" step="0.01" value={form.height} onChange={set("height")} /></div>
                <div className="form-group"><label className="label">Fitness Goal</label><select className="input" value={form.fitnessGoal} onChange={set("fitnessGoal")}>{GOALS.map(g => <option key={g}>{g}</option>)}</select></div>
                <div className="form-group"><label className="label">Activity Level</label><select className="input" value={form.activityLevel} onChange={set("activityLevel")}>{ACTS.map(a => <option key={a}>{a}</option>)}</select></div>
                <div className="form-group"><label className="label">Calorie Target</label><input className="input" type="number" value={form.dailyCalorieTarget} onChange={set("dailyCalorieTarget")} placeholder="2000" /></div>
                <div className="form-group"><label className="label">Water Target (ml)</label><input className="input" type="number" value={form.dailyWaterTarget} onChange={set("dailyWaterTarget")} placeholder="2500" /></div>
                <div className="form-group"><label className="label">Role</label><select className="input" value={form.role} onChange={set("role")}><option>USER</option><option>ADMIN</option></select></div>
              </div>
              <div style={{ display:"flex", gap:10, marginTop:18 }}>
                <button type="submit" className="btn btn-primary" style={{ flex:1 }}>{editing ? "Save Changes" : "Create User"}</button>
                <button type="button" className="btn btn-ghost" onClick={() => setShowModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
