// Get random meal from a meal type
export const getRandomMeal = (mealType) => {
  const meals = nigerianFoods[mealType] || [];
  return meals[Math.floor(Math.random() * meals.length)];
};

// Get meal suggestion for the day based on time
export const getMealSuggestion = () => {
  const hour = new Date().getHours();
  
  if (hour >= 5 && hour < 12) {
    return { type: "breakfast", meal: getRandomMeal("breakfast") };
  } else if (hour >= 12 && hour < 17) {
    return { type: "lunch", meal: getRandomMeal("lunch") };
  } else {
    return { type: "dinner", meal: getRandomMeal("dinner") };
  }
};

// Get all meals for a day
export const getDailyMealPlan = () => {
  return {
    breakfast: getRandomMeal("breakfast"),
    lunch: getRandomMeal("lunch"),
    dinner: getRandomMeal("dinner"),
  };
};
