import React, { useCallback, useEffect, useMemo, useState } from "react";
import API from "../api/axios";
import { getNigeriaDateKey, formatDateNigeria } from "../utils/timeUtils";
import { useAuth } from "../context/AuthContext";
import ReminderPanel from "../components/ReminderPanel";

const MEAL_ORDER = ["BREAKFAST", "LUNCH", "DINNER"];
const MEAL_ICONS = {
  BREAKFAST: "🍳",
  LUNCH: "🍛",
  DINNER: "🍲",
  SNACK: "🍎",
};

const formatTime = (value) => {
  if (!value) return "Flexible";
  const [hour = "00", minute = "00"] = value.split(":");
  const numericHour = Number(hour);
  const suffix = numericHour >= 12 ? "PM" : "AM";
  const displayHour = numericHour % 12 || 12;
  return `${displayHour}:${minute} ${suffix}`;
};

const titleCase = (value) => value?.charAt(0) + value?.slice(1).toLowerCase();

export default function Meals() {
  const { user } = useAuth();
  const [mealPlan, setMealPlan] = useState(null);
  const [weeklyPlan, setWeeklyPlan] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedMeal, setSelectedMeal] = useState(null);
  const [showDetails, setShowDetails] = useState(false);

  const loadMeals = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const [dailyRes, weeklyRes] = await Promise.allSettled([
        API.get(`/meals/user/${user.id}/plan`, {
          params: { date: getNigeriaDateKey() },
        }),
        API.get(`/meals/user/${user.id}/weekly-plan`, {
          params: { date: getNigeriaDateKey() },
        }),
      ]);

      if (dailyRes.status === "fulfilled") {
        setMealPlan(dailyRes.value.data || null);
      } else {
        setMealPlan(null);
      }

      if (weeklyRes.status === "fulfilled") {
        setWeeklyPlan(weeklyRes.value.data || null);
      } else {
        setWeeklyPlan(null);
      }

      if (dailyRes.status === "rejected" && weeklyRes.status === "rejected") {
        throw dailyRes.reason || weeklyRes.reason;
      }
    } catch (err) {
      console.error("Failed to load meal plan:", err);
      setError(err.response?.data?.message || "Could not load meal plan.");
      setMealPlan(null);
      setWeeklyPlan(null);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  useEffect(() => {
    loadMeals();
  }, [loadMeals]);

  const meals = useMemo(() => mealPlan?.meals || [], [mealPlan]);

  const primaryMeals = useMemo(
    () =>
      MEAL_ORDER.map((type) => meals.find((meal) => meal.mealType === type)).filter(Boolean),
    [meals]
  );

  const snackMeals = useMemo(
    () => meals.filter((meal) => !MEAL_ORDER.includes(meal.mealType)),
    [meals]
  );

  const totalProtein = meals.reduce((sum, meal) => sum + Number(meal.protein || 0), 0);
  const weeklyDays = useMemo(() => weeklyPlan?.days || [], [weeklyPlan]);

  if (!user) {
    return <div className="loading">Please log in to view meal planning.</div>;
  }

  if (loading) {
    return <div className="loading">Loading meal plan...</div>;
  }

  return (
    <div className="page fade-up">
      <div style={{ marginBottom: 24 }}>
        <h1 className="page-title">Meals 🥗</h1>
        <p className="page-sub">Backend meal plan • {formatDateNigeria()}</p>
      </div>

      {error && (
        <div
          className="card"
          style={{ marginBottom: 24, border: "1px solid #f59e0b", background: "rgba(245, 158, 11, 0.08)" }}
        >
          {error}
        </div>
      )}

      <div className="grid-3" style={{ marginBottom: 24 }}>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Total Calories</div>
          <div style={{ fontSize: 30, fontWeight: 800, color: "var(--accent3)" }}>
            {(mealPlan?.totalCalories || 0).toLocaleString()}
          </div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>kcal planned for today</div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Meal Entries</div>
          <div style={{ fontSize: 30, fontWeight: 800, color: "var(--accent)" }}>{meals.length}</div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>generated and saved by backend</div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Total Protein</div>
          <div style={{ fontSize: 30, fontWeight: 800, color: "var(--accent2)" }}>{totalProtein.toFixed(1)}</div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>grams across all meal entries</div>
        </div>
      </div>

      <div style={{ marginBottom: 24 }}>
        <ReminderPanel title="Meal Reminders" readOnly />
      </div>

      {weeklyDays.length > 0 && (
        <div className="card" style={{ marginBottom: 24 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 16 }}>
            <div>
              <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>This Week's Meal Shuffle</h3>
              <p style={{ margin: "4px 0 0 0", color: "var(--muted)", fontSize: 12 }}>
                Monday to Sunday suggestions reshuffle every new week and mix Nigerian and international meals.
              </p>
            </div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>
              Weekly total: <strong style={{ color: "var(--text)" }}>{(weeklyPlan?.totalCalories || 0).toLocaleString()} kcal</strong>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 12 }}>
            {weeklyDays.map((dayPlan) => {
              const dayName = new Date(dayPlan.date).toLocaleDateString("en-NG", { weekday: "long" });
              const dayMeals = Array.isArray(dayPlan.meals) ? dayPlan.meals : [];
              return (
                <div key={dayPlan.date} style={{ padding: 12, background: "var(--bg)", borderRadius: 8, border: "1px solid var(--border)" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                    <div>
                      <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase" }}>{dayName}</div>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text)" }}>{dayPlan.date}</div>
                    </div>
                    <div style={{ fontSize: 12, color: "var(--accent)" }}>{(dayPlan.totalCalories || 0).toLocaleString()} kcal</div>
                  </div>
                  <div style={{ display: "grid", gap: 8 }}>
                    {dayMeals.slice(0, 3).map((meal) => (
                      <div key={meal.id} style={{ display: "flex", justifyContent: "space-between", gap: 10, fontSize: 12 }}>
                        <div>
                          <span style={{ marginRight: 6 }}>{MEAL_ICONS[meal.mealType] || "🍽️"}</span>
                          <strong>{meal.mealName}</strong>
                        </div>
                        <span style={{ color: "var(--muted)" }}>{meal.mealType}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: 16, marginBottom: 24 }}>
        {primaryMeals.map((meal) => (
          <div
            key={meal.id}
            className="card"
            style={{ cursor: "pointer", borderLeft: "5px solid var(--accent)", transition: "all 0.2s ease" }}
            onClick={() => {
              setSelectedMeal(meal);
              setShowDetails(true);
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
              <div>
                <div style={{ fontSize: 28, marginBottom: 6 }}>{MEAL_ICONS[meal.mealType] || "🍽️"}</div>
                <h3 style={{ margin: "0 0 4px 0", color: "var(--text)" }}>{meal.mealName}</h3>
                <p style={{ margin: 0, fontSize: 13, color: "var(--muted)" }}>
                  {titleCase(meal.mealType)} • {formatTime(meal.mealTime)}
                </p>
              </div>
              <span
                className="badge"
                style={{
                  background: "var(--accent)",
                  color: "#fff",
                  padding: "4px 12px",
                  borderRadius: 4,
                }}
              >
                CLICK
              </span>
            </div>

            <p style={{ margin: "12px 0", fontSize: 13, color: "var(--muted)", lineHeight: 1.5 }}>{meal.description}</p>

            <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
              <span style={{ fontSize: 11, background: "var(--bg)", padding: "4px 10px", borderRadius: 4, color: "var(--accent)" }}>
                {meal.calories} kcal
              </span>
              <span style={{ fontSize: 11, background: "var(--bg)", padding: "4px 10px", borderRadius: 4, color: "var(--accent2)" }}>
                {Number(meal.protein || 0).toFixed(1)}g protein
              </span>
              <span style={{ fontSize: 11, background: "var(--bg)", padding: "4px 10px", borderRadius: 4, color: "var(--accent3)" }}>
                {meal.servingSize || "Serving set"}
              </span>
            </div>

            <button className="btn btn-primary" style={{ width: "100%", padding: "8px 12px", fontSize: 13 }}>
              View Details
            </button>
          </div>
        ))}
      </div>

      {snackMeals.length > 0 && (
        <div className="card" style={{ marginBottom: 24 }}>
          <h3 style={{ margin: "0 0 12px 0" }}>Additional Tracked Items</h3>
          <div style={{ display: "grid", gap: 10 }}>
            {snackMeals.map((meal) => (
              <div
                key={meal.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  gap: 12,
                  padding: 12,
                  borderRadius: 8,
                  background: "var(--bg)",
                  border: "1px solid var(--border)",
                }}
              >
                <div>
                  <div style={{ fontWeight: 600 }}>{meal.mealName}</div>
                  <div style={{ fontSize: 12, color: "var(--muted)" }}>
                    {meal.calories || 0} kcal • {formatTime(meal.mealTime)} • {meal.servingSize || "Snack"}
                  </div>
                </div>
                <span style={{ fontSize: 12, color: "var(--muted)" }}>Backend-tracked</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {showDetails && selectedMeal && (
        <div className="modal-overlay" onClick={() => setShowDetails(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
              <span style={{ fontSize: 32 }}>{MEAL_ICONS[selectedMeal.mealType] || "🍽️"}</span>
              <div>
                <h2 className="modal-title" style={{ margin: 0 }}>
                  {selectedMeal.mealName}
                </h2>
                <p style={{ margin: "4px 0 0 0", color: "var(--muted)", fontSize: 13 }}>
                  {titleCase(selectedMeal.mealType)} • {formatTime(selectedMeal.mealTime)}
                </p>
              </div>
            </div>

            <p style={{ color: "var(--muted)", lineHeight: 1.6, marginBottom: 16 }}>{selectedMeal.description}</p>

            <div className="card" style={{ background: "var(--bg)", marginBottom: 16 }}>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12 }}>
                <div>
                  <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 4 }}>Calories</div>
                  <div style={{ fontSize: 20, fontWeight: 700, color: "var(--accent)" }}>{selectedMeal.calories || 0}</div>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 4 }}>Protein</div>
                  <div style={{ fontSize: 20, fontWeight: 700, color: "var(--accent2)" }}>{Number(selectedMeal.protein || 0).toFixed(1)}g</div>
                </div>
                <div>
                  <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 4 }}>Carbs</div>
                  <div style={{ fontSize: 20, fontWeight: 700, color: "var(--accent3)" }}>{Number(selectedMeal.carbs || 0).toFixed(1)}g</div>
                </div>
              </div>
            </div>

            <div style={{ marginBottom: 16 }}>
              <h4 style={{ margin: "0 0 6px 0", fontSize: 13, textTransform: "uppercase", color: "var(--muted)" }}>
                Food Items
              </h4>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {String(selectedMeal.foodItems || "")
                  .split(",")
                  .map((item) => item.trim())
                  .filter(Boolean)
                  .map((item) => (
                    <span key={item} className="badge" style={{ background: "var(--bg)", color: "var(--text)", padding: "5px 10px" }}>
                      {item}
                    </span>
                  ))}
              </div>
            </div>

            <div style={{ marginBottom: 16 }}>
              <h4 style={{ margin: "0 0 6px 0", fontSize: 13, textTransform: "uppercase", color: "var(--muted)" }}>
                Serving Size
              </h4>
              <p style={{ margin: 0, color: "var(--text)" }}>{selectedMeal.servingSize || "Not specified"}</p>
            </div>

            <div style={{ display: "flex", gap: 10 }}>
              <button className="btn btn-primary" onClick={() => setShowDetails(false)}>
                Done
              </button>
              <button className="btn btn-ghost" onClick={() => setShowDetails(false)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
