import { Capacitor } from "@capacitor/core";
import { LocalNotifications } from "@capacitor/local-notifications";

// Alarm and notification service
// Schedules native reminders on Android/iPhone and falls back to web alerts in the browser.

const NIGERIA_TIMEZONE = "Africa/Lagos";
const SETTINGS_KEY = "fittracker.notificationSettings";
const ALARMS_KEY = "fittracker.alarms";
const ALARM_COUNTER_KEY = "fittracker.alarmCounter";

const DEFAULT_NOTIFICATION_SETTINGS = {
  enabled: true,
  sound: true,
  vibrate: true,
  workout: true,
  water: true,
  meal: true,
};

