import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  defaultAlarms,
  getAllAlarms,
  getNotificationStatus,
  initializeDefaultAlarms,
  requestNotificationPermission,
  toggleAlarm,
} from "../utils/alarmService";

const TYPE_LABELS = {
  workout: { label: "Workout", icon: "🏋️" },
  water: { label: "Water", icon: "💧" },
  meal: { label: "Meal", icon: "🍽️" },
};

const formatTime = (value) => {
  if (!value) return "--:--";
  const [hour = "00", minute = "00"] = value.split(":");
  const hourNumber = Number(hour);
  const suffix = hourNumber >= 12 ? "PM" : "AM";
  const displayHour = hourNumber % 12 || 12;
  return `${displayHour}:${minute} ${suffix}`;
};

export default function ReminderPanel({ title = "Alarms", readOnly = false }) {
  const [alarms, setAlarms] = useState([]);
  const [status, setStatus] = useState({ display: "loading", exact_alarm: "n/a" });
  const navigate = useNavigate();

  const refresh = async () => {
    setAlarms([...getAllAlarms()]);
    setStatus(await getNotificationStatus());
  };

  useEffect(() => {
    if (getAllAlarms().length === 0) {
      initializeDefaultAlarms();
    }
    void refresh();
  }, []);

  const grouped = useMemo(() => {
    const source = alarms.length > 0 ? alarms : defaultAlarms;
    return source.reduce((acc, alarm) => {
      const key = alarm.type || "meal";
      if (!acc[key]) acc[key] = [];
      acc[key].push(alarm);
      return acc;
    }, {});
  }, [alarms]);

  const enableNotifications = async () => {
    const granted = await requestNotificationPermission();
    if (granted && getAllAlarms().length === 0) {
      initializeDefaultAlarms();
    }
    await refresh();
  };

  const handleToggle = (alarmId) => {
    toggleAlarm(alarmId);
    void refresh();
  };

  return (
    <div className="card">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 14 }}>
        <div>
          <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{title}</h3>
          <p style={{ margin: "4px 0 0 0", fontSize: 12, color: "var(--muted)" }}>
            Meal, water, and workout alerts scheduled on the device.
          </p>
        </div>
        {readOnly ? (
          <button className="btn btn-primary" style={{ padding: "8px 12px", fontSize: 12 }} onClick={() => navigate("/settings")}>
            Manage in Settings
          </button>
        ) : (
          <button className="btn btn-primary" style={{ padding: "8px 12px", fontSize: 12 }} onClick={enableNotifications}>
            Enable on Device
          </button>
        )}
      </div>

      <div style={{ marginBottom: 12, fontSize: 12, color: "var(--muted)" }}>
        Device permission: <strong style={{ color: "var(--text)" }}>{status.display}</strong>
        {status.exact_alarm && status.exact_alarm !== "n/a" && status.exact_alarm !== "loading" ? (
          <span style={{ marginLeft: 12 }}>Exact alarms: <strong style={{ color: "var(--text)" }}>{status.exact_alarm}</strong></span>
        ) : null}
      </div>

      <div style={{ display: "grid", gap: 10 }}>
        {Object.entries(TYPE_LABELS).map(([type, meta]) => {
          const items = grouped[type] || [];
          return (
            <div key={type} style={{ padding: 12, background: "var(--bg)", border: "1px solid var(--border)", borderRadius: 8 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 8 }}>
                <div style={{ fontWeight: 700 }}>
                  <span style={{ marginRight: 8 }}>{meta.icon}</span>
                  {meta.label}
                </div>
                <div style={{ fontSize: 12, color: "var(--muted)" }}>{items.length} alert(s)</div>
              </div>
              <div style={{ display: "grid", gap: 8 }}>
                {items.map((alarm) => (
                  <div key={alarm.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 600 }}>{alarm.title}</div>
                      <div style={{ fontSize: 12, color: "var(--muted)" }}>{alarm.message}</div>
                      <div style={{ fontSize: 12, color: "var(--muted)" }}>At {formatTime(alarm.time)}</div>
                    </div>
                    {!readOnly && (
                      <button
                        className="btn"
                        style={{
                          padding: "6px 10px",
                          fontSize: 12,
                          border: "1px solid var(--border)",
                          background: alarm.enabled ? "var(--accent)" : "var(--card)",
                          color: alarm.enabled ? "#fff" : "var(--text)",
                        }}
                        onClick={() => handleToggle(alarm.id)}
                      >
                        {alarm.enabled ? "On" : "Off"}
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
