import axios from "axios";
// src/api/axios.js
const rawApiBaseUrl = process.env.REACT_APP_API_URL || "http://localhost:8081";
const normalizedApiBaseUrl = rawApiBaseUrl.replace(/\/$/, "");
const fallbackBaseUrls = [
  "http://127.0.0.1:8081",
  "http://localhost:8081",
  "http://10.0.2.2:8081",
  "http://172.20.10.3:8081",
  "http://172.20.10.2:8081",
  "http://172.16.16.176:8081",
]
  .map((url) => url.replace(/\/$/, ""))
  .filter((url, index, list) => list.indexOf(url) === index);

const cachedApiBaseUrl = localStorage.getItem("kenntyfit_api_base_url") || "";
let resolvedApiBaseUrl = "";
let resolvingBaseUrlPromise = null;

const toApiBaseUrl = (baseUrl) => (baseUrl.endsWith("/api") ? baseUrl : `${baseUrl}/api`);

const probeApiBaseUrl = async () => {
  if (resolvedApiBaseUrl) {
    return resolvedApiBaseUrl;
  }

  if (!resolvingBaseUrlPromise) {
    resolvingBaseUrlPromise = (async () => {
      const candidates = [
        normalizedApiBaseUrl,
        cachedApiBaseUrl,
        ...fallbackBaseUrls.filter((url) => url !== normalizedApiBaseUrl && url !== cachedApiBaseUrl),
      ].filter(Boolean).filter((url, index, list) => list.indexOf(url) === index);

      for (const candidate of candidates) {
        try {
          const controller = new AbortController();
          const timeout = window.setTimeout(() => controller.abort(), 3000);
          const response = await fetch(toApiBaseUrl(candidate).replace(/\/$/, "") + "/auth/health", {
            method: "GET",
            signal: controller.signal,
          });
          window.clearTimeout(timeout);
          if (response.ok) {
            resolvedApiBaseUrl = candidate;
            localStorage.setItem("kenntyfit_api_base_url", candidate);
            return candidate;
          }
        } catch (error) {
          // Try the next candidate.
        }
      }

      resolvedApiBaseUrl = normalizedApiBaseUrl;
      return resolvedApiBaseUrl;
    })().finally(() => {
      resolvingBaseUrlPromise = null;
    });
  }

  return resolvingBaseUrlPromise;
};

const API = axios.create({
  baseURL: toApiBaseUrl(resolvedApiBaseUrl || normalizedApiBaseUrl), // ✅ must match server.port=8081
});

API.interceptors.request.use((config) => {
  return probeApiBaseUrl().then((baseUrl) => {
    config.baseURL = toApiBaseUrl(baseUrl || normalizedApiBaseUrl);
    const finalUrl = `${config.baseURL.replace(/\/$/, "")}${config.url?.startsWith("/") ? "" : "/"}${config.url || ""}`;
    if (finalUrl.includes("undefined")) {
      console.warn("Request URL contains undefined:", finalUrl);
    }

    const token = localStorage.getItem("token");
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  });
});

API.interceptors.response.use(
  (response) => response,
  (error) => {
    const status = error.response?.status;

    if (status === 401) {
      localStorage.removeItem("token");
      localStorage.removeItem("user");
      window.location.href = "/login";
    }

    // Log errors for debugging but don't throw in critical paths
    if (error.response?.status >= 500) {
      console.error("Server error:", error.response.status, error.response.data);
    }

    return Promise.reject(error);
  }
);

export default API;
