import React, { createContext, useContext, useState, useEffect } from "react";
import API from "../api/axios";

const AuthContext = createContext(null);

const isNumericId = (value) => {
  if (value === null || value === undefined || value === "") return false;
  const numericValue = Number(value);
  return Number.isFinite(numericValue) && String(numericValue) === String(value).trim();
};

const extractUserSubjectFromToken = (token) => {
  try {
    if (!token) return null;
    const parts = token.split(".");
    if (parts.length !== 3) return null;
    const decoded = JSON.parse(atob(parts[1]));
    return decoded.sub || decoded.username || decoded.id || decoded.userId || null;
  } catch (e) {
    console.warn("Could not decode token:", e);
    return null;
  }
};

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const bootstrapAuth = async () => {
      const savedToken = localStorage.getItem("token");
      const savedUser = localStorage.getItem("user");

      if (!savedToken || !savedUser) {
        setLoading(false);
        return;
      }

      try {
        const parsedUser = JSON.parse(savedUser);
        let resolvedUser = parsedUser;

        if (!isNumericId(parsedUser.id) && parsedUser.username) {
          const profileRes = await API.get(`/users/username/${encodeURIComponent(parsedUser.username)}`);
          resolvedUser = profileRes.data;
        }

        if (!isNumericId(resolvedUser.id)) {
          const tokenSubject = extractUserSubjectFromToken(savedToken);
          if (tokenSubject) {
            const profileRes = await API.get(`/users/username/${encodeURIComponent(tokenSubject)}`);
            resolvedUser = profileRes.data;
          }
        }

        if (!isNumericId(resolvedUser.id)) {
          throw new Error("Could not resolve numeric user id.");
        }

        localStorage.setItem("user", JSON.stringify(resolvedUser));
        setUser(resolvedUser);
      } catch (err) {
        console.warn("Failed to restore authenticated user:", err);
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        setUser(null);
      } finally {
        setLoading(false);
      }
    };

    bootstrapAuth();
  }, []);

  const login = async (username, password) => {
    const res = await API.post("/auth/login", { username, password });
    if (res.data?.otpRequired) {
      return res.data;
    }

    const { token, ...userData } = res.data;
    if (!isNumericId(userData.id)) {
      const profileRes = await API.get(`/users/username/${encodeURIComponent(username)}`);
      Object.assign(userData, profileRes.data);
    }

    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(userData));
    setUser(userData);
    return res.data;
  };

  const verifyOtp = async (username, otp) => {
    const res = await API.post("/auth/verify-otp", { username, otp });
    const { token, ...userData } = res.data;

    if (!isNumericId(userData.id)) {
      const profileRes = await API.get(`/users/username/${encodeURIComponent(username)}`);
      Object.assign(userData, profileRes.data);
    }

    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(userData));
    setUser(userData);
    return res.data;
  };

  const resendOtp = async (username, password) => {
    const res = await API.post("/auth/resend-otp", { username, password });
    return res.data;
  };

  const register = async (username, email, password, profileData = {}) => {
    const payload = {
      username,
      email,
      password,
      firstName: profileData.firstName || "",
      lastName: profileData.lastName || "",
      age: profileData.age ? parseInt(profileData.age) : null,
      weight: profileData.weight ? parseFloat(profileData.weight) : null,
      height: profileData.height ? parseFloat(profileData.height) : null,
      gender: profileData.gender || "MALE",
      fitnessGoal: profileData.fitnessGoal || "WEIGHT_LOSS",
      activityLevel: profileData.activityLevel || "MODERATELY_ACTIVE",
      dailyCalorieTarget: profileData.dailyCalorieTarget ? parseInt(profileData.dailyCalorieTarget) : 2000,
      dailyWaterTarget: profileData.dailyWaterTarget ? parseInt(profileData.dailyWaterTarget) : 2500
    };
    const res = await API.post("/auth/register", payload);
    return res.data;
  };

  const forgotPassword = async (email) => {
    const res = await API.post("/auth/forgot-password", { email });
    return res.data;
  };

  const resetPassword = async (token, newPassword, confirmPassword) => {
    const res = await API.post("/auth/reset-password", {
      token,
      newPassword,
      confirmPassword
    });
    return res.data;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem("token");
    localStorage.removeItem("user");
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        login,
        verifyOtp,
        resendOtp,
        register,
        forgotPassword,
        resetPassword,
        logout,
        isAuthenticated: !!user
      }}
    >
      {!loading && children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
