import React, { useState, useEffect } from "react";
import { nigerianFoods, getMealSuggestion } from "../utils/nigerianFoods";

export default function MealSuggestions() {
  const [selectedMealType, setSelectedMealType] = useState("all");
  const [currentSuggestion, setCurrentSuggestion] = useState(null);
  const [favorites, setFavorites] = useState([]);

  // Load favorites from localStorage
  useEffect(() => {
    const saved = localStorage.getItem("favoriteMeals");
    if (saved) {
      setFavorites(JSON.parse(saved));
    }
  }, []);

  // Get initial suggestion based on time of day
  useEffect(() => {
    const suggestion = getMealSuggestion();
    setCurrentSuggestion(suggestion);
  }, []);

  // Save favorites to localStorage
  const toggleFavorite = (meal, mealType) => {
    const isFavorited = favorites.some(
      (fav) => fav.id === meal.id && fav.mealType === mealType
    );

    let updated;
    if (isFavorited) {
      updated = favorites.filter(
        (fav) => !(fav.id === meal.id && fav.mealType === mealType)
      );
    } else {
      updated = [...favorites, { ...meal, mealType }];
    }

    setFavorites(updated);
    localStorage.setItem("favoriteMeals", JSON.stringify(updated));
  };

  const isFavorited = (meal, mealType) => {
    return favorites.some((fav) => fav.id === meal.id && fav.mealType === mealType);
  };

  // Get meals to display
  const getMealsToDisplay = () => {
    if (selectedMealType === "all") {
      return Object.entries(nigerianFoods).flatMap(([type, meals]) =>
        meals.map((meal) => ({ ...meal, mealType: type }))
      );
    } else if (selectedMealType === "favorites") {
      return favorites;
    }
    return nigerianFoods[selectedMealType] || [];
  };

  const displayMeals = getMealsToDisplay();

  const getNewSuggestion = () => {
    const newSuggestion = getMealSuggestion();
    setCurrentSuggestion(newSuggestion);
  };

  return (
    <div style={{ padding: "20px", maxWidth: "1200px", margin: "0 auto" }}>
      {/* Header */}
      <div style={{ marginBottom: "30px" }}>
        <h1 style={{ fontSize: "32px", fontWeight: 700, marginBottom: "8px" }}>
          🍲  Food Suggestions
        </h1>
        <p style={{ color: "var(--muted)", fontSize: "14px" }}>
          Discover healthy Nigerian meals tailored to your fitness goals
        </p>
      </div>

      {/* Today's Suggestion Card */}
      {currentSuggestion && (
        <div
          style={{
            background: "linear-gradient(135deg, #00e5a0 0%, #00b887 100%)",
            borderRadius: "16px",
            padding: "24px",
            marginBottom: "30px",
            color: "white",
            boxShadow: "0 8px 24px rgba(0, 229, 160, 0.3)",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "16px", marginBottom: "16px" }}>
            <span style={{ fontSize: "48px" }}>{currentSuggestion.meal.image}</span>
            <div>
              <p style={{ fontSize: "12px", opacity: 0.9, textTransform: "uppercase", letterSpacing: "1px" }}>
                Today's {currentSuggestion.type}
              </p>
              <h2 style={{ fontSize: "24px", fontWeight: 700, margin: "4px 0" }}>
                {currentSuggestion.meal.name}
              </h2>
            </div>
          </div>
          <p style={{ fontSize: "14px", marginBottom: "16px", opacity: 0.95 }}>
            {currentSuggestion.meal.description}
          </p>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "12px", marginBottom: "16px" }}>
            <div style={{ background: "rgba(255,255,255,0.2)", padding: "12px", borderRadius: "8px" }}>
              <p style={{ fontSize: "12px", opacity: 0.9 }}>Calories</p>
              <p style={{ fontSize: "18px", fontWeight: 700 }}>{currentSuggestion.meal.calories}</p>
            </div>
            <div style={{ background: "rgba(255,255,255,0.2)", padding: "12px", borderRadius: "8px" }}>
              <p style={{ fontSize: "12px", opacity: 0.9 }}>Protein</p>
              <p style={{ fontSize: "18px", fontWeight: 700 }}>{currentSuggestion.meal.protein}</p>
            </div>
            <div style={{ background: "rgba(255,255,255,0.2)", padding: "12px", borderRadius: "8px" }}>
              <p style={{ fontSize: "12px", opacity: 0.9 }}>Prep Time</p>
              <p style={{ fontSize: "18px", fontWeight: 700 }}>{currentSuggestion.meal.prepTime}</p>
            </div>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
            <button
              onClick={getNewSuggestion}
              style={{
                background: "rgba(255,255,255,0.2)",
                border: "1px solid white",
                color: "white",
                padding: "10px 20px",
                borderRadius: "8px",
                cursor: "pointer",
                fontWeight: 600,
                fontSize: "14px",
                transition: "background 0.3s",
              }}
              onMouseEnter={(e) => (e.target.style.background = "rgba(255,255,255,0.3)")}
              onMouseLeave={(e) => (e.target.style.background = "rgba(255,255,255,0.2)")}
            >
              🔄 Get Another Idea
            </button>
            <button
              onClick={() =>
                toggleFavorite(currentSuggestion.meal, currentSuggestion.type)
              }
              style={{
                background: isFavorited(currentSuggestion.meal, currentSuggestion.type)
                  ? "rgba(255,255,255,0.3)"
                  : "rgba(255,255,255,0.2)",
                border: "1px solid white",
                color: "white",
                padding: "10px 20px",
                borderRadius: "8px",
                cursor: "pointer",
                fontWeight: 600,
                fontSize: "14px",
                transition: "background 0.3s",
              }}
              onMouseEnter={(e) => (e.target.style.background = "rgba(255,255,255,0.3)")}
              onMouseLeave={(e) => (e.target.style.background = isFavorited(currentSuggestion.meal, currentSuggestion.type) ? "rgba(255,255,255,0.3)" : "rgba(255,255,255,0.2)")}
            >
              {isFavorited(currentSuggestion.meal, currentSuggestion.type) ? "❤️" : "🤍"} Save to Favorites
            </button>
          </div>
        </div>
      )}

      {/* Filter Tabs */}
      <div style={{ display: "flex", gap: "8px", marginBottom: "24px", flexWrap: "wrap" }}>
        {["all", "breakfast", "lunch", "dinner", "favorites"].map((type) => (
          <button
            key={type}
            onClick={() => setSelectedMealType(type)}
            style={{
              padding: "8px 16px",
              borderRadius: "8px",
              border: "none",
              background:
                selectedMealType === type ? "var(--accent)" : "var(--card)",
              color: selectedMealType === type ? "white" : "var(--text)",
              cursor: "pointer",
              fontWeight: selectedMealType === type ? 600 : 500,
              fontSize: "14px",
              transition: "all 0.3s",
              textTransform: "capitalize",
            }}
          >
            {type === "all"
              ? "All Meals"
              : type === "favorites"
              ? `❤️ Favorites (${favorites.length})`
              : type.charAt(0).toUpperCase() + type.slice(1)}
          </button>
        ))}
      </div>

      {/* Meals Grid */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: "20px" }}>
        {displayMeals.length > 0 ? (
          displayMeals.map((meal, idx) => (
            <div
              key={`${meal.id}-${meal.mealType || selectedMealType}-${idx}`}
              style={{
                background: "var(--card)",
                borderRadius: "12px",
                overflow: "hidden",
                border: "1px solid var(--border)",
                transition: "all 0.3s",
                display: "flex",
                flexDirection: "column",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = "translateY(-4px)";
                e.currentTarget.style.boxShadow =
                  "0 12px 24px rgba(0, 229, 160, 0.2)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = "translateY(0)";
                e.currentTarget.style.boxShadow = "none";
              }}
            >
              {/* Image */}
              <div
                style={{
                  background: "linear-gradient(135deg, #00e5a0 0%, #00b887 100%)",
                  padding: "40px 20px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "60px",
                  position: "relative",
                }}
              >
                {meal.image}
                <button
                  onClick={() =>
                    toggleFavorite(
                      meal,
                      meal.mealType || selectedMealType
                    )
                  }
                  style={{
                    position: "absolute",
                    top: "12px",
                    right: "12px",
                    background: "white",
                    border: "none",
                    borderRadius: "50%",
                    width: "32px",
                    height: "32px",
                    cursor: "pointer",
                    fontSize: "16px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transition: "background 0.3s",
                  }}
                  onMouseEnter={(e) => (e.target.style.background = "#f0f0f0")}
                  onMouseLeave={(e) => (e.target.style.background = "white")}
                >
                  {isFavorited(meal, meal.mealType || selectedMealType) ? "❤️" : "🤍"}
                </button>
              </div>

              {/* Content */}
              <div style={{ padding: "16px", flex: 1, display: "flex", flexDirection: "column" }}>
                <h3 style={{ fontSize: "16px", fontWeight: 700, marginBottom: "6px" }}>
                  {meal.name}
                </h3>
                <p
                  style={{
                    fontSize: "13px",
                    color: "var(--muted)",
                    marginBottom: "12px",
                    flex: 1,
                  }}
                >
                  {meal.description}
                </p>

                {/* Stats */}
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px", marginBottom: "12px" }}>
                  <div style={{ background: "rgba(0, 229, 160, 0.1)", padding: "8px", borderRadius: "6px" }}>
                    <p style={{ fontSize: "11px", color: "var(--muted)" }}>Calories</p>
                    <p style={{ fontSize: "14px", fontWeight: 700 }}>
                      {meal.calories}
                    </p>
                  </div>
                  <div style={{ background: "rgba(0, 229, 160, 0.1)", padding: "8px", borderRadius: "6px" }}>
                    <p style={{ fontSize: "11px", color: "var(--muted)" }}>Protein</p>
                    <p style={{ fontSize: "14px", fontWeight: 700 }}>
                      {meal.protein}
                    </p>
                  </div>
                </div>

                {/* Ingredients */}
                <div style={{ marginBottom: "12px" }}>
                  <p style={{ fontSize: "11px", color: "var(--muted)", marginBottom: "6px" }}>
                    Ingredients
                  </p>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "4px" }}>
                    {meal.ingredients.slice(0, 3).map((ing, i) => (
                      <span
                        key={i}
                        style={{
                          fontSize: "11px",
                          background: "rgba(0, 229, 160, 0.15)",
                          padding: "4px 8px",
                          borderRadius: "4px",
                          color: "var(--accent)",
                        }}
                      >
                        {ing}
                      </span>
                    ))}
                    {meal.ingredients.length > 3 && (
                      <span
                        style={{
                          fontSize: "11px",
                          color: "var(--muted)",
                          padding: "4px 8px",
                        }}
                      >
                        +{meal.ingredients.length - 3}
                      </span>
                    )}
                  </div>
                </div>

                {/* Prep Time */}
                <div style={{ fontSize: "12px", color: "var(--muted)" }}>
                  ⏱️ {meal.prepTime}
                </div>
              </div>
            </div>
          ))
        ) : (
          <div style={{ gridColumn: "1 / -1", textAlign: "center", padding: "40px 20px" }}>
            <p style={{ fontSize: "16px", color: "var(--muted)" }}>
              {selectedMealType === "favorites"
                ? "No favorites yet! Add some meals to your favorites."
                : "No meals found."}
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
