import React, { useCallback, useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Camera, CameraResultType, CameraSource } from "@capacitor/camera";
import { useAuth } from "../context/AuthContext";
import API from "../api/axios";

const isNumericId = (value) => {
  if (value === null || value === undefined || value === "") return false;
  const numericValue = Number(value);
  return Number.isFinite(numericValue) && String(numericValue) === String(value).trim();
};

const resolveAssetUrl = (value) => {
  if (!value) return null;
  if (value.startsWith("data:") || value.startsWith("blob:") || /^https?:\/\//i.test(value)) {
    return value;
  }
  return new URL(value, API.defaults.baseURL).toString();
};

const dataUrlToFile = async (dataUrl, filename) => {
  const response = await fetch(dataUrl);
  const blob = await response.blob();
  return new File([blob], filename, { type: blob.type || "image/jpeg" });
};

export default function Profile() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const fileInputRef = useRef(null);

  const [profile, setProfile] = useState(null);
  const [sub, setSub] = useState(null);
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({});
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");
  const [tab, setTab] = useState("profile");
  const [showImageMenu, setShowImageMenu] = useState(false);
  const [loading, setLoading] = useState(true);
  const [uploadingImage, setUploadingImage] = useState(false);

  const applyProfile = useCallback((data) => {
    if (!data) return;
    setProfile((current) => ({ ...(current || {}), ...data }));
    setForm((current) => ({ ...(current || {}), ...data }));
  }, []);

  const resolveUserId = useCallback(async () => {
    if (isNumericId(user?.id)) {
      return Number(user.id);
    }

    if (user?.username) {
      const response = await API.get(`/users/username/${encodeURIComponent(user.username)}`);
      if (isNumericId(response.data?.id)) {
        return Number(response.data.id);
      }
    }

    throw new Error("Unable to resolve user profile.");
  }, [user?.id, user?.username]);

  const refreshProfile = useCallback(async () => {
    const resolvedId = await resolveUserId();
    const [profileRes, subRes] = await Promise.allSettled([
      API.get(`/users/${resolvedId}`),
      API.get(`/subscriptions/user/${resolvedId}`),
    ]);

    if (profileRes.status === "fulfilled") {
      applyProfile(profileRes.value.data);
    }

    if (subRes.status === "fulfilled") {
      setSub(subRes.value.data);
    }
  }, [applyProfile, resolveUserId]);

  useEffect(() => {
    let mounted = true;

    const loadProfile = async () => {
      if (!user) {
        if (mounted) setLoading(false);
        return;
      }

      if (mounted) setLoading(true);
      if (mounted) {
        applyProfile(user);
      }

      try {
        await refreshProfile();
      } catch (err) {
        if (mounted) {
          applyProfile(user);
          setError(err.response?.data?.message || "Could not load profile from the backend.");
        }
      } finally {
        if (mounted) setLoading(false);
      }
    };

    loadProfile();

    return () => {
      mounted = false;
    };
  }, [applyProfile, user, refreshProfile]);

  const set = (key) => (value) => setForm((current) => ({ ...current, [key]: value }));

  const uploadProfilePicture = async (file) => {
    if (!file) return;

    setUploadingImage(true);
    setError("");
    setSuccess("");

    try {
      const resolvedId = await resolveUserId();
      const formData = new FormData();
      formData.append("file", file);

      const response = await API.post(`/users/${resolvedId}/profile-picture`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setProfile(response.data);
      setForm(response.data);
      setShowImageMenu(false);
      setSuccess("Profile picture updated.");
      setTimeout(() => setSuccess(""), 3000);
    } catch (err) {
      setError(err.response?.data?.message || "Image upload failed.");
    } finally {
      setUploadingImage(false);
    }
  };

  const handleImageUpload = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    await uploadProfilePicture(file);
  };

  const handleTakeSelfie = async () => {
    try {
      const image = await Camera.getPhoto({
        quality: 90,
        allowEditing: true,
        resultType: CameraResultType.DataUrl,
        source: CameraSource.Camera,
      });

      if (image.dataUrl) {
        const file = await dataUrlToFile(image.dataUrl, `profile-${Date.now()}.jpg`);
        await uploadProfilePicture(file);
      } else {
        setShowImageMenu(false);
      }
    } catch (err) {
      setShowImageMenu(false);
      setError(err?.message || "Camera capture failed.");
    }
  };

  const handleRemovePhoto = async () => {
    if (!window.confirm("Remove your profile picture?")) return;

    setUploadingImage(true);
    setError("");
    setSuccess("");

    try {
      const resolvedId = await resolveUserId();
      const response = await API.delete(`/users/${resolvedId}/profile-picture`);
      setProfile(response.data);
      setForm(response.data);
      setShowImageMenu(false);
      setSuccess("Profile picture removed.");
      setTimeout(() => setSuccess(""), 3000);
    } catch (err) {
      setError(err.response?.data?.message || "Could not remove profile picture.");
    } finally {
      setUploadingImage(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError("");
    setSuccess("");

    try {
      const resolvedId = await resolveUserId();
      const response = await API.put(`/users/${resolvedId}`, form);
      applyProfile(response.data);
      setProfile((current) => ({ ...current, profilePicture: current?.profilePicture || response.data.profilePicture }));
      setForm((current) => ({ ...current, profilePicture: current?.profilePicture || response.data.profilePicture }));
      setEditing(false);
      setShowImageMenu(false);
      setSuccess("Profile updated!");
      setTimeout(() => setSuccess(""), 3000);
    } catch (err) {
      setError(err.response?.data?.message || "Update failed.");
    } finally {
      setSaving(false);
    }
  };

  if (loading && !profile) return <div className="loading">Loading profile...</div>;
  if (!profile) return <div className="loading">Profile data is unavailable.</div>;

  const isAdmin = profile.role === "ADMIN" || profile.role === "ROLE_ADMIN";
  const profilePhoto = resolveAssetUrl(profile.profilePicture);

  const F = ({ label, k, type = "text", opts }) => (
    <div className="form-group">
      <label className="label">{label}</label>
      {opts ? (
        <select className="input" value={form[k] || ""} onChange={(e) => set(k)(e.target.value)}>
          {opts.map((o) => (
            <option key={o.v} value={o.v}>
              {o.l}
            </option>
          ))}
        </select>
      ) : (
        <input className="input" type={type} value={form[k] || ""} onChange={(e) => set(k)(e.target.value)} />
      )}
    </div>
  );

  return (
    <div className="page fade-up">
      {error && (
        <div className="card" style={{ marginBottom: 16, border: "1px solid #f59e0b", background: "rgba(245, 158, 11, 0.08)" }}>
          {error}
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 24 }}>
        <div style={{ position: "relative", flexShrink: 0, overflow: "visible" }}>
          <div
            style={{
              width: 60,
              height: 60,
              borderRadius: "50%",
              background: profilePhoto ? "transparent" : "rgba(0,153,255,0.12)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: "var(--font-display)",
              fontSize: 22,
              fontWeight: 800,
              color: "var(--accent2)",
              overflow: "hidden",
              cursor: "pointer",
              position: "relative",
            }}
            onClick={() => {
              if (!editing) {
                setEditing(true);
              }
              setShowImageMenu((open) => !open);
            }}
            title="Click to change image"
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                if (!editing) {
                  setEditing(true);
                }
                setShowImageMenu((open) => !open);
              }
            }}
          >
            {profilePhoto ? (
              <img src={profilePhoto} alt="profile" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            ) : (
              profile.firstName?.[0] || profile.username?.[0] || "U"
            )}
            {editing && (
              <div style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.4)", display: "flex", alignItems: "center", justifyContent: "center", color: "white", fontSize: 24 }}>
                📷
              </div>
            )}
          </div>

          {editing && showImageMenu && (
            <div style={{ position: "absolute", top: "calc(100% + 8px)", left: 0, background: "var(--card)", border: "1px solid var(--border)", borderRadius: 8, padding: 0, minWidth: 170, zIndex: 1000, boxShadow: "0 4px 12px rgba(0,0,0,0.15)" }}>
              <button
                onClick={handleTakeSelfie}
                disabled={uploadingImage}
                style={{ width: "100%", padding: "10px 12px", textAlign: "left", background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "var(--text)", borderBottom: "1px solid var(--border)", display: "flex", alignItems: "center", gap: 8 }}
              >
                📸 Take Selfie
              </button>
              <button
                onClick={() => fileInputRef.current?.click()}
                disabled={uploadingImage}
                style={{ width: "100%", padding: "10px 12px", textAlign: "left", background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "var(--text)", borderBottom: "1px solid var(--border)", display: "flex", alignItems: "center", gap: 8 }}
              >
                📁 Upload File
              </button>
              <button
                onClick={handleRemovePhoto}
                disabled={uploadingImage || !profile.profilePicture}
                style={{ width: "100%", padding: "10px 12px", textAlign: "left", background: "none", border: "none", cursor: "pointer", fontSize: 13, color: "var(--accent3)", display: "flex", alignItems: "center", gap: 8 }}
              >
                🗑 Remove Photo
              </button>
            </div>
          )}
          <input ref={fileInputRef} type="file" accept="image/*" onChange={handleImageUpload} style={{ display: "none" }} />
        </div>

        <div>
          <h1 style={{ fontFamily: "var(--font-display)", fontSize: 20, fontWeight: 800, color: "var(--text)", marginBottom: 4 }}>
            {profile.firstName} {profile.lastName || ""}
          </h1>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <span style={{ fontSize: 13, color: "var(--muted)" }}>@{profile.username}</span>
            {isAdmin && <span className="badge badge-red" style={{ fontSize: 10 }}>Admin</span>}
            {sub?.status === "ACTIVE" && <span className="badge badge-green" style={{ fontSize: 10 }}>{sub.plan} Plan</span>}
          </div>
        </div>

        <button className="btn btn-danger" style={{ marginLeft: "auto", fontSize: 13 }} onClick={() => { logout(); navigate("/login"); }}>
          Sign Out
        </button>
      </div>

      {success && <div className="alert alert-success" style={{ marginBottom: 14 }}>✅ {success}</div>}
      {error && <div className="alert alert-error" style={{ marginBottom: 14 }}>⚠️ {error}</div>}

      <div style={{ display: "flex", gap: 8, marginBottom: 22 }}>
        {["profile", "targets", "subscription"].map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className="btn"
            style={{ padding: "7px 16px", fontSize: 13, fontWeight: tab === t ? 700 : 400, background: tab === t ? "var(--accent)" : "var(--card)", color: tab === t ? "#0a0e1a" : "var(--muted)", border: "1px solid var(--border)", textTransform: "capitalize" }}
          >
            {t === "targets" ? "Daily Targets" : t.charAt(0).toUpperCase() + t.slice(1)}
          </button>
        ))}
      </div>

      {tab === "profile" && (
        <div className="card">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
            <div style={{ fontSize: 14, fontWeight: 700 }}>Personal Information</div>
            {!editing ? (
              <button className="btn btn-ghost" style={{ fontSize: 13 }} onClick={() => setEditing(true)}>
                Edit
              </button>
            ) : (
              <div style={{ display: "flex", gap: 8 }}>
                <button className="btn btn-primary" style={{ fontSize: 13 }} onClick={handleSave} disabled={saving || uploadingImage}>
                  {saving ? "Saving..." : "Save"}
                </button>
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 13 }}
                  onClick={() => {
                    setEditing(false);
                    setForm(profile);
                    setShowImageMenu(false);
                  }}
                >
                  Cancel
                </button>
              </div>
            )}
          </div>

          {editing ? (
            <div className="form-grid">
              <F label="First Name" k="firstName" />
              <F label="Last Name" k="lastName" />
              <F label="Email" k="email" type="email" />
              <F label="Age" k="age" type="number" />
              <F label="Weight (kg)" k="weight" type="number" />
              <F label="Height (m)" k="height" type="number" />
              <F label="Gender" k="gender" opts={[{ v: "MALE", l: "Male" }, { v: "FEMALE", l: "Female" }, { v: "OTHER", l: "Other" }]} />
              <F label="Fitness Goal" k="fitnessGoal" opts={[{ v: "WEIGHT_LOSS", l: "Weight Loss" }, { v: "MUSCLE_GAIN", l: "Muscle Gain" }, { v: "MAINTAIN_WEIGHT", l: "Maintain" }, { v: "IMPROVE_FITNESS", l: "Improve Fitness" }]} />
              <F label="Activity Level" k="activityLevel" opts={[{ v: "SEDENTARY", l: "Sedentary" }, { v: "LIGHTLY_ACTIVE", l: "Lightly Active" }, { v: "MODERATELY_ACTIVE", l: "Moderately Active" }, { v: "VERY_ACTIVE", l: "Very Active" }, { v: "EXTRA_ACTIVE", l: "Extra Active" }]} />
            </div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              {[
                ["Name", `${profile.firstName || ""} ${profile.lastName || ""}`],
                ["Username", `@${profile.username}`],
                ["Email", profile.email],
                ["Age", profile.age ? `${profile.age} yrs` : "—"],
                ["Gender", profile.gender || "—"],
                ["Weight", profile.weight ? `${profile.weight} kg` : "—"],
                ["Height", profile.height ? `${profile.height} m` : "—"],
                ["Goal", profile.fitnessGoal?.replace(/_/g, " ") || "—"],
                ["Activity", profile.activityLevel?.replace(/_/g, " ") || "—"],
                ["Member since", profile.createdAt?.split("T")[0] || "—"],
              ].map(([k, v]) => (
                <div key={k} style={{ background: "var(--bg2)", borderRadius: 8, padding: "10px 12px" }}>
                  <div style={{ fontSize: 10, color: "var(--muted)", marginBottom: 3 }}>{k}</div>
                  <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text)" }}>{v || "—"}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {tab === "targets" && (
        <div className="card">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
            <div style={{ fontSize: 14, fontWeight: 700 }}>Daily Targets</div>
            {!editing ? (
              <button className="btn btn-ghost" style={{ fontSize: 13 }} onClick={() => setEditing(true)}>
                Edit
              </button>
            ) : (
              <div style={{ display: "flex", gap: 8 }}>
                <button className="btn btn-primary" style={{ fontSize: 13 }} onClick={handleSave} disabled={saving || uploadingImage}>
                  {saving ? "Saving..." : "Save"}
                </button>
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 13 }}
                  onClick={() => {
                    setEditing(false);
                    setForm(profile);
                    setShowImageMenu(false);
                  }}
                >
                  Cancel
                </button>
              </div>
            )}
          </div>

          {editing ? (
            <div className="form-grid">
              <div className="form-group">
                <label className="label">Calorie Target (kcal)</label>
                <input className="input" type="number" value={form.dailyCalorieTarget || ""} onChange={(e) => set("dailyCalorieTarget")(Number(e.target.value))} placeholder="2000" />
              </div>
              <div className="form-group full">
                <label className="label">Water Target (ml)</label>
                <input className="input" type="number" value={form.dailyWaterTarget || ""} onChange={(e) => set("dailyWaterTarget")(Number(e.target.value))} placeholder="2500" />
              </div>
            </div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 14 }}>
              {[
                { l: "Daily Calories", v: profile.dailyCalorieTarget, u: "kcal", c: "var(--accent3)", i: "🔥" },
                { l: "Daily Water", v: profile.dailyWaterTarget, u: "ml", c: "var(--accent2)", i: "💧" },
              ].map((t) => (
                <div key={t.l} style={{ background: "var(--bg2)", borderRadius: 10, padding: 16, borderTop: `3px solid ${t.c}` }}>
                  <div style={{ fontSize: 20, marginBottom: 8 }}>{t.i}</div>
                  <div style={{ fontSize: 10, color: "var(--muted)", textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 4 }}>{t.l}</div>
                  <div style={{ fontFamily: "var(--font-display)", fontSize: 24, fontWeight: 800, color: t.c }}>
                    {t.v?.toLocaleString() || "—"}
                    <span style={{ fontSize: 11, color: "var(--muted)", marginLeft: 3 }}>{t.u}</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {tab === "subscription" && (
        sub ? (
          <div className="card">
            <div style={{ fontSize: 14, fontWeight: 700, marginBottom: 18 }}>Current Subscription</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 18 }}>
              {[
                ["Plan", sub.plan],
                ["Status", sub.status],
                ["Amount", sub.amount ? `₦${Number(sub.amount).toLocaleString()}` : "Free"],
                ["Started", sub.startDate],
                ["Expires", sub.endDate],
                ["Days Left", sub.daysRemaining ? `${sub.daysRemaining} days` : "—"],
              ].map(([k, v]) => (
                <div key={k} style={{ background: "var(--bg2)", borderRadius: 8, padding: "10px 12px" }}>
                  <div style={{ fontSize: 10, color: "var(--muted)", marginBottom: 3 }}>{k}</div>
                  <div style={{ fontSize: 13, fontWeight: 600, color: k === "Status" && v === "ACTIVE" ? "var(--accent)" : k === "Status" ? "var(--accent3)" : "var(--text)" }}>
                    {v || "—"}
                  </div>
                </div>
              ))}
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <button className="btn btn-primary" style={{ fontSize: 13 }} onClick={() => navigate("/pricing")}>
                Upgrade / Renew
              </button>
              {sub.status === "ACTIVE" && (
                <button
                  className="btn btn-ghost"
                  style={{ fontSize: 13, color: "var(--accent3)" }}
                  onClick={async () => {
                    if (window.confirm("Cancel subscription?")) {
                      try {
                        await API.post(`/subscriptions/user/${user.id}/cancel`);
                        setSub((current) => ({ ...current, status: "CANCELLED" }));
                        setSuccess("Subscription cancelled.");
                        setTimeout(() => setSuccess(""), 3000);
                      } catch {
                        setError("Could not cancel.");
                      }
                    }
                  }}
                >
                  Cancel Subscription
                </button>
              )}
            </div>
          </div>
        ) : (
          <div className="card" style={{ textAlign: "center", padding: 40 }}>
            <div style={{ fontSize: 28, marginBottom: 12 }}>📋</div>
            <div style={{ color: "var(--muted)", marginBottom: 18 }}>No active subscription found.</div>
            <button className="btn btn-primary" onClick={() => navigate("/pricing")}>
              View Plans →
            </button>
          </div>
        )
      )}
    </div>
  );
}
