import React, { useEffect, useState } from "react";
import { Capacitor } from "@capacitor/core";
import {
  getNotificationStatus,
  getNotificationSettings,
  requestNotificationPermission,
  requestExactNotificationPermission,
  resetNotificationSettings,
  updateNotificationSettings,
} from "../utils/alarmService";

const SwitchRow = ({ label, description, checked, onChange, disabled }) => (
  <label style={{ display: "flex", justifyContent: "space-between", gap: 16, alignItems: "center", padding: "12px 0", borderBottom: "1px solid var(--border)" }}>
    <div>
      <div style={{ fontWeight: 600, color: "var(--text)" }}>{label}</div>
      <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 4, lineHeight: 1.5 }}>{description}</div>
    </div>
    <input type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} disabled={disabled} />
  </label>
);

export default function NotificationSettings() {
  const [status, setStatus] = useState({ display: "loading", exact_alarm: "n/a" });
  const [settings, setSettings] = useState(() => getNotificationSettings());
  const [saved, setSaved] = useState("");
  const isAndroid = Capacitor.getPlatform() === "android";

  const refreshStatus = async () => {
    setStatus(await getNotificationStatus());
  };

  useEffect(() => {
    setSettings(getNotificationSettings());
    void refreshStatus();
  }, []);

  const handleSave = () => {
    const next = updateNotificationSettings(settings);
    setSettings(next);
    void refreshStatus();
    setSaved("Saved");
    setTimeout(() => setSaved(""), 2000);
  };

  const handleReset = () => {
    const next = resetNotificationSettings();
    setSettings(next);
    void refreshStatus();
    setSaved("Reset");
    setTimeout(() => setSaved(""), 2000);
  };

  const enableNotifications = async () => {
    const granted = await requestNotificationPermission();
    await refreshStatus();
    if (granted) {
      setSettings((current) => ({ ...current, enabled: true }));
    }
  };

  const enableExactAlarms = async () => {
    await requestExactNotificationPermission();
    await refreshStatus();
  };

  return (
    <div className="card">
      <div style={{ display: "flex", justifyContent: "space-between", gap: 12, alignItems: "center", marginBottom: 12 }}>
        <div>
          <h3 style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>Notifications</h3>
          <p style={{ margin: "4px 0 0 0", fontSize: 12, color: "var(--muted)" }}>
            Native alarms, vibration, and device permissions are controlled here.
          </p>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
          <button className="btn btn-primary" style={{ padding: "8px 12px", fontSize: 12 }} onClick={enableNotifications}>
            Enable on Device
          </button>
          {isAndroid && status.exact_alarm !== "granted" && status.exact_alarm !== "loading" ? (
            <button className="btn" style={{ padding: "8px 12px", fontSize: 12, border: "1px solid var(--border)", background: "var(--card)" }} onClick={enableExactAlarms}>
              Allow Exact Alarms
            </button>
          ) : null}
        </div>
      </div>

      <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 10 }}>
        Device permission: <strong style={{ color: "var(--text)" }}>{status.display}</strong>
        {isAndroid && status.exact_alarm !== "loading" ? (
          <>
            <span style={{ marginLeft: 12 }}>Exact alarms: <strong style={{ color: "var(--text)" }}>{status.exact_alarm}</strong></span>
          </>
        ) : null}
        {saved ? <span style={{ marginLeft: 12, color: "var(--accent)" }}>{saved}</span> : null}
      </div>

      <SwitchRow
        label="Master switch"
        description="Turn native notifications and app alerts on or off."
        checked={settings.enabled}
        onChange={(value) => setSettings((current) => ({ ...current, enabled: value }))}
      />
      <SwitchRow
        label="Workout alerts"
        description="Allow workout reminder alarms."
        checked={settings.workout}
        onChange={(value) => setSettings((current) => ({ ...current, workout: value }))}
      />
      <SwitchRow
        label="Water alerts"
        description="Allow hydration reminder alarms."
        checked={settings.water}
        onChange={(value) => setSettings((current) => ({ ...current, water: value }))}
      />
      <SwitchRow
        label="Meal alerts"
        description="Allow meal reminder alarms."
        checked={settings.meal}
        onChange={(value) => setSettings((current) => ({ ...current, meal: value }))}
      />
      <SwitchRow
        label="Sound"
        description="Keep alert sound behavior enabled for supported devices."
        checked={settings.sound}
        onChange={(value) => setSettings((current) => ({ ...current, sound: value }))}
      />
      <SwitchRow
        label="Vibration"
        description="Vibrate on supported devices when an alarm fires."
        checked={settings.vibrate}
        onChange={(value) => setSettings((current) => ({ ...current, vibrate: value }))}
      />

      <div style={{ display: "flex", gap: 10, marginTop: 14 }}>
        <button className="btn btn-primary" onClick={handleSave}>Save Settings</button>
        <button className="btn" onClick={handleReset} style={{ border: "1px solid var(--border)", background: "var(--card)" }}>
          Reset Defaults
        </button>
      </div>
    </div>
  );
}
