import React, { useCallback, useEffect, useMemo, useState } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine } from "recharts";
import API from "../api/axios";
import { useAuth } from "../context/AuthContext";
import { getNigeriaTime, formatDateNigeria } from "../utils/timeUtils";
import ReminderPanel from "../components/ReminderPanel";

const DEFAULT_GOAL = 2500;

const toDateKey = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const buildDateRange = (days = 7) => {
  const today = getNigeriaTime();
  const start = new Date(today);
  start.setDate(start.getDate() - (days - 1));
  return {
    startDate: toDateKey(start),
    endDate: toDateKey(today),
    todayKey: toDateKey(today),
  };
};

const formatTimeLabel = (timeValue) => {
  if (!timeValue) return "--:--";
  const [hour = "00", minute = "00"] = timeValue.split(":");
  const hourNumber = Number(hour);
  const suffix = hourNumber >= 12 ? "PM" : "AM";
  const displayHour = hourNumber % 12 || 12;
  return `${displayHour}:${minute} ${suffix}`;
};

const formatReminderLabel = (value) => {
  if (!value) return "";
  return formatTimeLabel(value);
};

const formatConfidence = (value) => {
  if (value == null || Number.isNaN(Number(value))) return "--";
  return `${Math.round(Number(value) * 100)}%`;
};

const getMotivation = (percentage) => {
  if (percentage < 25) return { emoji: "💧", text: "Just getting started. Keep drinking." };
  if (percentage < 50) return { emoji: "💦", text: "Good progress. Stay consistent." };
  if (percentage < 75) return { emoji: "🌊", text: "You are more than halfway there." };
  if (percentage < 100) return { emoji: "🏊", text: "Almost at your hydration goal." };
  return { emoji: "🏆", text: "Goal reached. Keep the rhythm going." };
};

export default function Water() {
  const { user } = useAuth();
  const [status, setStatus] = useState(null);
  const [todayEntries, setTodayEntries] = useState([]);
  const [weeklyEntries, setWeeklyEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadWaterData = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");

    const { startDate, endDate, todayKey } = buildDateRange(7);

    try {
      const [statusRes, todayRes, weekRes] = await Promise.all([
        API.get(`/water-intake/user/${user.id}/status`),
        API.get(`/water-intake/user/${user.id}/date/${todayKey}`),
        API.get(`/water-intake/user/${user.id}/date-range`, { params: { startDate, endDate } }),
      ]);

      setStatus(statusRes.data || null);
      setTodayEntries(Array.isArray(todayRes.data) ? todayRes.data : []);
      setWeeklyEntries(Array.isArray(weekRes.data) ? weekRes.data : []);
    } catch (err) {
      console.error("Failed to load water data:", err);
      setError(err.response?.data?.message || "Could not load hydration data.");
      setStatus(null);
      setTodayEntries([]);
      setWeeklyEntries([]);
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  useEffect(() => {
    loadWaterData();
  }, [loadWaterData]);

  useEffect(() => {
    const handleAutoTracked = () => {
      void loadWaterData();
    };

    window.addEventListener("hydrationAutoTracked", handleAutoTracked);
    return () => window.removeEventListener("hydrationAutoTracked", handleAutoTracked);
  }, [loadWaterData]);

  const weeklyData = useMemo(() => {
    const map = new Map();
    const now = getNigeriaTime();

    for (let i = 6; i >= 0; i -= 1) {
      const date = new Date(now);
      date.setDate(date.getDate() - i);
      const key = toDateKey(date);
      map.set(key, {
        key,
        day: date.toLocaleDateString("en-NG", { weekday: "short" }),
        ml: 0,
      });
    }

    weeklyEntries.forEach((entry) => {
      if (!entry?.intakeDate || !map.has(entry.intakeDate)) return;
      map.get(entry.intakeDate).ml += Number(entry.amountMl || 0);
    });

    return Array.from(map.values());
  }, [weeklyEntries]);

  const orderedEntries = useMemo(
    () => [...todayEntries].sort((a, b) => String(b.detectedAt || b.intakeTime || "").localeCompare(String(a.detectedAt || a.intakeTime || ""))),
    [todayEntries]
  );

  const targetWaterMl = status?.targetWaterMl || user?.dailyWaterTarget || DEFAULT_GOAL;
  const totalWaterMl = status?.totalWaterMl || 0;
  const remainingWaterMl = status?.remainingWaterMl ?? Math.max(targetWaterMl - totalWaterMl, 0);
  const progressPercentage = Math.min(100, status?.progressPercentage ?? Math.round((totalWaterMl / Math.max(targetWaterMl, 1)) * 100));
  const motivation = getMotivation(progressPercentage);
  const reminders = Array.isArray(status?.reminderTimes) ? status.reminderTimes : [];

  if (!user) {
    return <div className="loading">Please log in to view hydration tracking.</div>;
  }

  if (loading) {
    return <div className="loading">Loading hydration data...</div>;
  }

  return (
    <div className="page fade-up">
      <div style={{ marginBottom: 24 }}>
        <h1 className="page-title">Hydration 💧</h1>
        <p className="page-sub">{formatDateNigeria()} • Daily Goal: {targetWaterMl.toLocaleString()} ml</p>
      </div>

      {error && (
        <div
          className="card"
          style={{ marginBottom: 24, border: "1px solid #f59e0b", background: "rgba(245, 158, 11, 0.08)", color: "var(--text)" }}
        >
          {error}
        </div>
      )}

      <div className="card" style={{ marginBottom: 24 }}>
        <h3 style={{ margin: 0, fontSize: 14, fontWeight: 700 }}>Liquid Detection</h3>
        <p style={{ margin: "8px 0 0 0", fontSize: 12, color: "var(--muted)", lineHeight: 1.6 }}>
          When the phone or wristwatch detects a drinking motion, the app asks whether it was water.
        </p>
      </div>

      <div style={{ marginBottom: 24 }}>
        <ReminderPanel title="Hydration and Meal Alarms" readOnly />
      </div>

      <div
        className="card"
        style={{ background: "linear-gradient(135deg, #00B4DB 0%, #0083B0 100%)", color: "#fff", marginBottom: 24 }}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 16, marginBottom: 20 }}>
          <div>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", textTransform: "uppercase", marginBottom: 6 }}>
              Today's Hydration
            </div>
            <div style={{ fontSize: 36, fontWeight: 700, lineHeight: 1 }}>{totalWaterMl.toLocaleString()}</div>
            <div style={{ fontSize: 13, color: "rgba(255,255,255,0.8)", marginTop: 4 }}>
              of {targetWaterMl.toLocaleString()} ml
            </div>
          </div>
          <span style={{ fontSize: 48 }}>{motivation.emoji}</span>
        </div>

        <div style={{ height: 10, background: "rgba(255,255,255,0.2)", borderRadius: 5, overflow: "hidden", marginBottom: 12 }}>
          <div
            style={{
              height: "100%",
              background: "rgba(255,255,255,0.92)",
              width: `${progressPercentage}%`,
              transition: "width 0.3s ease",
            }}
          />
        </div>

        <div style={{ fontSize: 13, color: "rgba(255,255,255,0.92)" }}>
          {remainingWaterMl === 0 ? "Goal reached." : `${remainingWaterMl.toLocaleString()} ml to go • ${progressPercentage}%`}
        </div>

        <p style={{ margin: "12px 0 0 0", fontSize: 14, color: "rgba(255,255,255,0.92)" }}>
          {motivation.text}
        </p>
      </div>

      <div className="grid-3" style={{ marginBottom: 24 }}>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Sensor Tracked</div>
          <div style={{ fontSize: 28, fontWeight: 800, color: "var(--accent2)" }}>
            {(status?.sensorTrackedWaterMl || 0).toLocaleString()}
          </div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>ml detected from phone/watch input</div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Detections Today</div>
          <div style={{ fontSize: 28, fontWeight: 800, color: "var(--accent)" }}>
            {(status?.sensorDetectionCount || 0).toLocaleString()}
          </div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>
            {(status?.estimatedDetectionCount || 0).toLocaleString()} estimated from sip or container data
          </div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Soft Drinks</div>
          <div style={{ fontSize: 28, fontWeight: 800, color: "var(--accent3)" }}>
            {(status?.softDrinkCount || 0).toLocaleString()}
          </div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>logged separately from water</div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 8 }}>Last Detection</div>
          <div style={{ fontSize: 18, fontWeight: 700, color: "var(--text)" }}>
            {status?.lastRecordedAt ? new Date(status.lastRecordedAt).toLocaleTimeString("en-NG", { hour: "2-digit", minute: "2-digit", hour12: true }) : "No data"}
          </div>
          <div style={{ fontSize: 12, color: "var(--muted)" }}>{status?.timezone || "Africa/Lagos"}</div>
        </div>
      </div>

      <div className="grid-2" style={{ marginBottom: 24 }}>
        <div className="card">
          <h3 style={{ fontSize: 14, fontWeight: 700, margin: "0 0 14px 0" }}>Confirmation Tracking</h3>
          <p style={{ margin: 0, color: "var(--muted)", fontSize: 13, lineHeight: 1.6 }}>
            The app now asks you to confirm water after a liquid detection. If it is not water, nothing is saved.
          </p>
          <div style={{ marginTop: 12, display: "flex", flexWrap: "wrap", gap: 8 }}>
            <span style={{ padding: "6px 12px", background: "var(--bg)", borderRadius: 20, fontSize: 12, border: "1px solid var(--border)" }}>
              📱 Phone
            </span>
            <span style={{ padding: "6px 12px", background: "var(--bg)", borderRadius: 20, fontSize: 12, border: "1px solid var(--border)" }}>
              ⌚ Wristwatch
            </span>
            <span style={{ padding: "6px 12px", background: "var(--bg)", borderRadius: 20, fontSize: 12, border: "1px solid var(--border)" }}>
              🎯 On-body motion
            </span>
          </div>
        </div>

        <div className="card">
          <h3 style={{ fontSize: 14, fontWeight: 700, margin: "0 0 14px 0" }}>Upcoming Reminders</h3>
          {reminders.length ? (
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {reminders.map((reminder) => (
                <span
                  key={reminder}
                  style={{
                    padding: "6px 12px",
                    background: "var(--bg)",
                    borderRadius: 20,
                    fontSize: 12,
                    color: "var(--text)",
                    border: "1px solid var(--border)",
                  }}
                >
                  🔔 {formatReminderLabel(reminder)}
                </span>
              ))}
            </div>
          ) : (
            <p style={{ margin: 0, color: "var(--muted)", fontSize: 13 }}>No reminder slots returned for today.</p>
          )}
        </div>
      </div>

      <div className="card" style={{ marginBottom: 24 }}>
        <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 16, margin: "0 0 16px 0" }}>Last 7 Days</h3>
        <ResponsiveContainer width="100%" height={220}>
          <BarChart data={weeklyData}>
            <XAxis dataKey="day" tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
            <Tooltip
              contentStyle={{
                background: "var(--bg2)",
                border: "1px solid var(--border)",
                borderRadius: 8,
                fontSize: 12,
              }}
            />
            <ReferenceLine
              y={targetWaterMl}
              stroke="var(--accent)"
              strokeDasharray="5 5"
              label={{ value: "Goal", position: "top", fill: "var(--muted)", fontSize: 11 }}
            />
            <Bar dataKey="ml" fill="var(--accent)" radius={[6, 6, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {orderedEntries.length > 0 ? (
        <div className="card" style={{ marginBottom: 0 }}>
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, margin: "0 0 12px 0" }}>Today's Intake Log</h3>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {orderedEntries.map((entry) => (
              <div
                key={`${entry.id}-${entry.detectedAt || entry.intakeTime}`}
                style={{
                  padding: 12,
                  background: "var(--bg)",
                  borderRadius: 8,
                  border: "1px solid var(--border)",
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 6 }}>
                  <span style={{ fontSize: 14 }}>
                    💧 <strong>{Number(entry.amountMl || 0).toLocaleString()} ml</strong>
                  </span>
                  <span style={{ color: "var(--muted)", fontSize: 12 }}>{formatTimeLabel(entry.intakeTime)}</span>
                </div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 6 }}>
                  <span style={{ fontSize: 11, padding: "3px 8px", borderRadius: 20, background: "var(--card)" }}>
                    {String(entry.sourceDevice || "PHONE").replaceAll("_", " ")}
                  </span>
                  <span style={{ fontSize: 11, padding: "3px 8px", borderRadius: 20, background: "var(--card)" }}>
                    {String(entry.sensorType || "MOTION_PATTERN").replaceAll("_", " ")}
                  </span>
                  <span style={{ fontSize: 11, padding: "3px 8px", borderRadius: 20, background: "var(--card)" }}>
                    {String(entry.beverageType || "WATER").replaceAll("_", " ")}
                  </span>
                  <span style={{ fontSize: 11, padding: "3px 8px", borderRadius: 20, background: "var(--card)" }}>
                    {entry.sensorEstimated ? "Estimated" : "Recorded"}
                  </span>
                  <span style={{ fontSize: 11, padding: "3px 8px", borderRadius: 20, background: "var(--card)" }}>
                    {formatConfidence(entry.confidenceScore)}
                  </span>
                </div>
                <div style={{ fontSize: 12, color: "var(--muted)", lineHeight: 1.5 }}>
                  {entry.sipCount ? `${entry.sipCount} sips` : "Direct ml record"}
                  {entry.containerSizeMl ? ` • ${entry.containerSizeMl} ml container` : ""}
                  {entry.consumedPercentage ? ` • ${entry.consumedPercentage}% consumed` : ""}
                </div>
              </div>
            ))}
          </div>

          <div
            style={{
              marginTop: 12,
              paddingTop: 12,
              borderTop: "1px solid var(--border)",
              fontWeight: 600,
              color: "var(--accent)",
            }}
          >
            Total Today: {totalWaterMl.toLocaleString()} ml
          </div>
        </div>
      ) : (
        <div
          style={{
            textAlign: "center",
            padding: "40px 20px",
            color: "var(--muted)",
          }}
        >
          <div style={{ fontSize: 32, marginBottom: 12 }}>💧</div>
          <p>No water detected yet today.</p>
          <p style={{ fontSize: 13, margin: "8px 0 0 0" }}>The app waits for a confirmation before it stores a water record.</p>
        </div>
      )}
    </div>
  );
}
