import React, { useCallback, useEffect, useMemo, useState } from "react";
import { BarChart, Bar, LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";
import API from "../api/axios";
import { useAuth } from "../context/AuthContext";
import { getNigeriaTime, formatDateNigeria, getGreeting } from "../utils/timeUtils";
import ReminderPanel from "../components/ReminderPanel";

const TT = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  return (
    <div
      style={{
        background: "var(--bg3)",
        border: "1px solid var(--border)",
        borderRadius: 8,
        padding: "8px 12px",
        fontSize: 12,
      }}
    >
      <p style={{ color: "var(--muted)", marginBottom: 4 }}>{label}</p>
      {payload.map((point) => (
        <p key={point.name} style={{ color: point.color }}>
          {point.name}: <strong>{point.value}</strong>
        </p>
      ))}
    </div>
  );
};

function StatCard({ color, icon, label, value, unit, pct }) {
  return (
    <div
      style={{
        background: "var(--card)",
        border: "1px solid var(--border)",
        borderRadius: "var(--radius)",
        padding: 16,
        position: "relative",
        overflow: "hidden",
      }}
    >
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 3, background: color }} />
      <div style={{ fontSize: 22, marginBottom: 8 }}>{icon}</div>
      <div
        style={{
          fontSize: 11,
          color: "var(--muted)",
          textTransform: "uppercase",
          letterSpacing: "0.06em",
          marginBottom: 6,
        }}
      >
        {label}
      </div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 4 }}>
        <span style={{ fontSize: 28, fontWeight: 800, fontFamily: "var(--font-display)", color }}>{value}</span>
        <span style={{ fontSize: 12, color: "var(--muted)" }}>{unit}</span>
      </div>
      {pct != null && (
        <div style={{ marginTop: 10, height: 3, borderRadius: 2, background: "var(--border)", overflow: "hidden" }}>
          <div
            style={{
              height: "100%",
              borderRadius: 2,
              width: `${Math.min(100, pct)}%`,
              background: color,
              transition: "width 0.6s ease",
            }}
          />
        </div>
      )}
    </div>
  );
}

const toDateKey = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const mealTypeIcon = (mealType) => {
  switch (mealType) {
    case "BREAKFAST":
      return "🍳";
    case "LUNCH":
      return "🍛";
    case "DINNER":
      return "🍲";
    case "SNACK":
      return "🍎";
    default:
      return "🍽️";
  }
};

const getActivity = (steps) => {
  if (steps >= 10000) return { level: "Excellent", emoji: "🔥", color: "green" };
  if (steps >= 7000) return { level: "Active", emoji: "💪", color: "green" };
  if (steps >= 4000) return { level: "Steady", emoji: "🚶", color: "orange" };
  return { level: "Starting", emoji: "📈", color: "gray" };
};

export default function Dashboard() {
  const { user } = useAuth();
  const [greeting, setGreeting] = useState(null);
  const [resolvedUserId, setResolvedUserId] = useState(null);
  const [resolvingUserId, setResolvingUserId] = useState(true);
  const [mealPlan, setMealPlan] = useState(null);
  const [weeklyMealPlan, setWeeklyMealPlan] = useState(null);
  const [todayMeals, setTodayMeals] = useState([]);
  const [waterStatus, setWaterStatus] = useState(null);
  const [waterWeeklyData, setWaterWeeklyData] = useState([]);
  const [workoutRoutine, setWorkoutRoutine] = useState(null);
  const [workoutSummary, setWorkoutSummary] = useState(null);
  const [weeklySummary, setWeeklySummary] = useState(null);
  const [stepChartData, setStepChartData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const loadDashboardData = useCallback(async () => {
    if (!user?.username && !user?.id) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setGreeting(getGreeting());

    const today = getNigeriaTime();
    const startDate = new Date(today);
    startDate.setDate(startDate.getDate() - 6);
    const todayKey = toDateKey(today);
    const userId = resolvedUserId || user?.id;

    if (!userId) {
      setLoading(false);
      setError("Could not resolve your dashboard user id.");
      return;
    }

    try {
      const [
        mealPlanRes,
        weeklyMealPlanRes,
        mealsRes,
        waterStatusRes,
        waterRangeRes,
        workoutRoutineRes,
        workoutSummaryRes,
        weeklySummaryRes,
        workoutsRangeRes,
      ] = await Promise.allSettled([
        API.get(`/meals/user/${userId}/plan`, { params: { date: todayKey } }),
        API.get(`/meals/user/${userId}/weekly-plan`, { params: { date: todayKey } }),
        API.get(`/meals/user/${userId}/date/${todayKey}`),
        API.get(`/water-intake/user/${userId}/status`),
        API.get(`/water-intake/user/${userId}/date-range`, {
          params: { startDate: toDateKey(startDate), endDate: todayKey },
        }),
        API.get(`/workouts/user/${userId}/routine`),
        API.get(`/workouts/user/${userId}/summary`),
        API.get(`/progress/user/${userId}/weekly-summary`),
        API.get(`/workouts/user/${userId}/date-range`, {
          params: { startDate: toDateKey(startDate), endDate: todayKey },
        }),
      ]);

      const failures = [];

      if (mealPlanRes.status === "fulfilled") {
        setMealPlan(mealPlanRes.value.data || null);
      } else {
        setMealPlan(null);
        failures.push("meal plan");
      }

      if (weeklyMealPlanRes.status === "fulfilled") {
        setWeeklyMealPlan(weeklyMealPlanRes.value.data || null);
      } else {
        setWeeklyMealPlan(null);
        failures.push("weekly meal plan");
      }

      if (mealsRes.status === "fulfilled") {
        setTodayMeals(Array.isArray(mealsRes.value.data) ? mealsRes.value.data : []);
      } else {
        setTodayMeals([]);
        failures.push("today's meals");
      }

      if (waterStatusRes.status === "fulfilled") {
        setWaterStatus(waterStatusRes.value.data || null);
      } else {
        setWaterStatus(null);
        failures.push("water status");
      }

      if (waterRangeRes.status === "fulfilled") {
        // handled below
      } else {
        failures.push("water history");
      }

      if (workoutRoutineRes.status === "fulfilled") {
        setWorkoutRoutine(workoutRoutineRes.value.data || null);
      } else {
        setWorkoutRoutine(null);
        failures.push("workout routine");
      }

      if (workoutSummaryRes.status === "fulfilled") {
        setWorkoutSummary(workoutSummaryRes.value.data || null);
      } else {
        setWorkoutSummary(null);
        failures.push("workout summary");
      }

      if (weeklySummaryRes.status === "fulfilled") {
        setWeeklySummary(weeklySummaryRes.value.data || null);
      } else {
        setWeeklySummary(null);
        failures.push("weekly progress");
      }

      if (workoutsRangeRes.status === "fulfilled") {
        // handled below
      } else {
        failures.push("workout history");
      }

      const waterRange = waterRangeRes.status === "fulfilled" && Array.isArray(waterRangeRes.value.data) ? waterRangeRes.value.data : [];
      const workoutsRange = workoutsRangeRes.status === "fulfilled" && Array.isArray(workoutsRangeRes.value.data) ? workoutsRangeRes.value.data : [];

      const waterMap = new Map();
      const stepMap = new Map();

      for (let i = 6; i >= 0; i -= 1) {
        const date = new Date(today);
        date.setDate(date.getDate() - i);
        const key = toDateKey(date);
        const day = date.toLocaleDateString("en-NG", { weekday: "short" });
        waterMap.set(key, { day, ml: 0 });
        stepMap.set(key, { dayName: day, steps: 0 });
      }

      waterRange.forEach((entry) => {
        if (!entry?.intakeDate || !waterMap.has(entry.intakeDate)) return;
        waterMap.get(entry.intakeDate).ml += Number(entry.amountMl || 0);
      });

      workoutsRange.forEach((entry) => {
        if (!entry?.workoutDate || !stepMap.has(entry.workoutDate)) return;
        stepMap.get(entry.workoutDate).steps += Number(entry.stepCount || 0);
      });

      setWaterWeeklyData(Array.from(waterMap.values()));
      setStepChartData(Array.from(stepMap.values()));

      if (failures.length > 0) {
        setError(`Some dashboard sections could not load: ${failures.join(", ")}.`);
      }
    } catch (err) {
      console.error("Failed to load dashboard data:", err);
      setMealPlan(null);
      setWeeklyMealPlan(null);
      setTodayMeals([]);
      setWaterStatus(null);
      setWaterWeeklyData([]);
      setWorkoutRoutine(null);
      setWorkoutSummary(null);
      setWeeklySummary(null);
      setStepChartData([]);
      setError(err.response?.data?.message || "Unable to load dashboard data from the backend.");
    } finally {
      setLoading(false);
    }
  }, [resolvedUserId, user?.id, user?.username]);

  useEffect(() => {
    let cancelled = false;

    const resolveDashboardUser = async () => {
      if (!user) {
        setResolvingUserId(false);
        setLoading(false);
        return;
      }

      try {
        if (user?.id != null && Number.isFinite(Number(user.id))) {
          const response = await API.get(`/users/${Number(user.id)}`);
          if (!cancelled && response.data?.id != null) {
            setResolvedUserId(Number(response.data.id));
            return;
          }
        }

        if (user?.username) {
          const response = await API.get(`/users/username/${encodeURIComponent(user.username)}`);
          if (!cancelled && response.data?.id != null) {
            setResolvedUserId(Number(response.data.id));
            return;
          }
        }
      } catch (err) {
        if (!cancelled && user?.username) {
          try {
            const response = await API.get(`/users/username/${encodeURIComponent(user.username)}`);
            if (response.data?.id != null) {
              setResolvedUserId(Number(response.data.id));
              return;
            }
          } catch (fallbackErr) {
            setResolvedUserId(null);
            setError(fallbackErr.response?.data?.message || "Could not resolve your dashboard user.");
          }
        } else if (!cancelled) {
          setResolvedUserId(null);
          setError(err.response?.data?.message || "Could not resolve your dashboard user.");
        }
      } finally {
        if (!cancelled) {
          setResolvingUserId(false);
        }
      }
    };

    resolveDashboardUser();

    return () => {
      cancelled = true;
    };
  }, [user]);

  useEffect(() => {
    if (!user || resolvingUserId) return;
    loadDashboardData();
  }, [loadDashboardData, user, resolvedUserId, resolvingUserId]);

  const waterGoal = waterStatus?.targetWaterMl || user?.dailyWaterTarget || 2500;
  const waterToday = waterStatus?.totalWaterMl || 0;
  const totalMealCalories = todayMeals.reduce((sum, meal) => sum + Number(meal.calories || 0), 0);
  const activity = useMemo(() => getActivity(workoutSummary?.totalSteps || 0), [workoutSummary?.totalSteps]);

  const featuredMeals = useMemo(() => {
    const order = ["BREAKFAST", "LUNCH", "DINNER"];
    return order.map((type) => todayMeals.find((meal) => meal.mealType === type)).filter(Boolean);
  }, [todayMeals]);

  const weeklyMealDays = useMemo(() => weeklyMealPlan?.days || [], [weeklyMealPlan]);

  if (loading || !greeting) {
    return <div className="loading">Loading dashboard...</div>;
  }

  return (
    <div className="page fade-up">
      {error && (
        <div style={{ 
          background: "rgba(255,165,0,0.1)", 
          border: "1px solid rgba(255,165,0,0.5)", 
          borderRadius: 8, 
          padding: 12, 
          marginBottom: 20,
          fontSize: 13,
          color: "var(--text)"
        }}>
          {error}
        </div>
      )}
      <h1 className="page-title">
        {greeting.text} {user?.firstName || user?.username || "User"} 👋
      </h1>
      <p className="page-sub">{formatDateNigeria()}</p>

      <div className="grid-4" style={{ marginBottom: 24 }}>
        <StatCard
          color="var(--accent)"
          icon="🚶"
          label="Steps Today"
          value={(workoutSummary?.totalSteps || 0).toLocaleString()}
          unit={`/ ${(weeklySummary?.averageDailySteps || 10000).toLocaleString()} avg`}
          pct={weeklySummary?.averageDailySteps ? ((workoutSummary?.totalSteps || 0) / weeklySummary.averageDailySteps) * 100 : null}
        />
        <StatCard
          color="var(--accent2)"
          icon="💧"
          label="Water Today"
          value={waterToday.toLocaleString()}
          unit={`/ ${waterGoal} ml`}
          pct={waterGoal ? (waterToday / waterGoal) * 100 : null}
        />
        <StatCard
          color="var(--accent3)"
          icon="🥗"
          label="Meal Entries"
          value={todayMeals.length}
          unit="today"
          pct={featuredMeals.length ? (todayMeals.length / featuredMeals.length) * 100 : null}
        />
        <StatCard
          color="var(--accent4)"
          icon="🔥"
          label="Meal Calories"
          value={totalMealCalories.toLocaleString()}
          unit="kcal"
          pct={mealPlan?.totalCalories ? (totalMealCalories / mealPlan.totalCalories) * 100 : null}
        />
      </div>

      <div style={{ marginBottom: 24 }}>
        <ReminderPanel title="Daily Alarms" readOnly />
      </div>

      <div className="grid-2" style={{ marginBottom: 24 }}>
        <div
          className="card"
          style={{
            background: activity.color === "green" ? "linear-gradient(135deg, #00BFA5 0%, #00897B 100%)" : "var(--card)",
            color: activity.color === "green" ? "#fff" : "var(--text)",
          }}
        >
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, margin: "0 0 14px 0" }}>Activity Level</h3>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <span style={{ fontSize: 48 }}>{activity.emoji}</span>
            <div>
              <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 4 }}>{activity.level}</div>
              <div style={{ fontSize: 13, opacity: 0.9 }}>
                {(workoutSummary?.totalSteps || 0).toLocaleString()} steps
                <br />
                {(workoutSummary?.totalCaloriesBurned || 0).toLocaleString()} kcal burned
              </div>
            </div>
          </div>
        </div>

        <div className="card">
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 14, margin: "0 0 14px 0" }}>This Week</h3>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
            <div style={{ background: "var(--bg)", padding: 12, borderRadius: 8 }}>
              <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 6 }}>Steps</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: "var(--accent)" }}>
                {(weeklySummary?.totalSteps || 0).toLocaleString()}
              </div>
            </div>
            <div style={{ background: "var(--bg)", padding: 12, borderRadius: 8 }}>
              <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase", marginBottom: 6 }}>Active Days</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: "var(--accent2)" }}>
                {(weeklySummary?.activeDays || 0).toLocaleString()}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="grid-2" style={{ marginBottom: 24 }}>
        <div className="card">
          <h3 style={{ fontFamily: "var(--font-display)", fontWeight: 700, marginBottom: 16, fontSize: 15 }}>Steps — last 7 days</h3>
          <ResponsiveContainer width="100%" height={180}>
            <BarChart data={stepChartData}>
              <XAxis dataKey="dayName" tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <Tooltip content={<TT />} />
              <Bar dataKey="steps" fill="var(--accent)" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="card">
          <h3 style={{ fontFamily: "var(--font-display)", fontWeight: 700, marginBottom: 16, fontSize: 15 }}>Water — last 7 days</h3>
          <ResponsiveContainer width="100%" height={180}>
            <LineChart data={waterWeeklyData}>
              <XAxis dataKey="day" tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: "var(--muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
              <Tooltip content={<TT />} />
              <Line type="monotone" dataKey="ml" stroke="var(--accent2)" strokeWidth={2} dot={{ fill: "var(--accent2)", r: 4 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid-2">
        <div className="card">
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, margin: "0 0 12px 0" }}>Today's Meal Plan</h3>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
            {featuredMeals.map((meal) => (
              <div
                key={meal.id}
                style={{
                  background: "var(--bg)",
                  color: "var(--text)",
                  padding: 10,
                  borderRadius: 8,
                  fontSize: 12,
                }}
              >
                <div style={{ fontSize: 10, opacity: 0.8, marginBottom: 4, textTransform: "uppercase" }}>{meal.mealType}</div>
                <div style={{ fontSize: 18, marginBottom: 4 }}>{mealTypeIcon(meal.mealType)}</div>
                <div style={{ fontWeight: 600, fontSize: 11, marginBottom: 2 }}>{meal.mealName}</div>
                <div style={{ fontSize: 10, opacity: 0.8 }}>{meal.calories || 0} kcal</div>
              </div>
            ))}
          </div>
        </div>

        <div className="card">
          <h3 style={{ fontSize: 14, fontWeight: 700, marginBottom: 12, margin: "0 0 12px 0" }}>Today's Workout</h3>
          <div style={{ display: "flex", alignItems: "flex-start", gap: 12 }}>
            <span style={{ fontSize: 40 }}>🏋️</span>
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, fontSize: 13, marginBottom: 4 }}>{workoutRoutine?.routineName || "Routine unavailable"}</div>
              <div style={{ fontSize: 12, color: "var(--muted)", marginBottom: 8, lineHeight: 1.4 }}>
                {workoutRoutine?.description || "The backend did not return a workout routine."}
              </div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                {(workoutRoutine?.exercises || []).slice(0, 3).map((exercise) => (
                  <span key={exercise} style={{ fontSize: 11, background: "var(--bg)", padding: "3px 8px", borderRadius: 4 }}>
                    {exercise}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {weeklyMealDays.length > 0 && (
        <div className="card" style={{ marginTop: 24, marginBottom: 24 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, marginBottom: 16 }}>
            <div>
              <h3 style={{ fontSize: 14, fontWeight: 700, margin: 0 }}>This Week's Meal Shuffle</h3>
              <p style={{ margin: "4px 0 0 0", fontSize: 12, color: "var(--muted)" }}>
                Nigerian meals and familiar international meals rotate from Monday to Sunday.
              </p>
            </div>
            <div style={{ fontSize: 12, color: "var(--muted)" }}>
              Weekly calories: <strong style={{ color: "var(--text)" }}>{(weeklyMealPlan?.totalCalories || 0).toLocaleString()} kcal</strong>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 12 }}>
            {weeklyMealDays.map((dayPlan) => {
              const dayName = new Date(dayPlan.date).toLocaleDateString("en-NG", { weekday: "long" });
              const dayMeals = Array.isArray(dayPlan.meals) ? dayPlan.meals : [];

              return (
                <div key={dayPlan.date} style={{ padding: 12, background: "var(--bg)", borderRadius: 8, border: "1px solid var(--border)" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, marginBottom: 10 }}>
                    <div>
                      <div style={{ fontSize: 11, color: "var(--muted)", textTransform: "uppercase" }}>{dayName}</div>
                      <div style={{ fontSize: 13, fontWeight: 700, color: "var(--text)" }}>{dayPlan.date}</div>
                    </div>
                    <div style={{ fontSize: 12, color: "var(--accent)" }}>{(dayPlan.totalCalories || 0).toLocaleString()} kcal</div>
                  </div>
                  <div style={{ display: "grid", gap: 8 }}>
                    {dayMeals.slice(0, 3).map((meal) => (
                      <div key={meal.id} style={{ display: "flex", justifyContent: "space-between", gap: 10, fontSize: 12 }}>
                        <div style={{ minWidth: 0 }}>
                          <span style={{ marginRight: 6 }}>{mealTypeIcon(meal.mealType)}</span>
                          <strong>{meal.mealName}</strong>
                        </div>
                        <span style={{ color: "var(--muted)", whiteSpace: "nowrap" }}>{meal.mealType}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}
