import { useEffect } from "react";
import { Capacitor } from "@capacitor/core";
import { useAuth } from "../context/AuthContext";
import { startHydrationAutoTracking, stopHydrationAutoTracking } from "../services/hydrationAutoTracker";

export default function AutoHydrationTracker() {
  const { user } = useAuth();

  useEffect(() => {
    const run = async () => {
      if (!user?.id || Capacitor.getPlatform() === "web") {
        await stopHydrationAutoTracking();
        return;
      }

      await startHydrationAutoTracking({ userId: user.id, sourceDevice: "PHONE" });
    };

    void run();

    return () => {
      void stopHydrationAutoTracking();
    };
  }, [user?.id]);

  return null;
}
