import React, { useEffect, useMemo, useRef } from "react";

const WORKOUT_VIDEOS = {
  FAT_LOSS: {
    src: "https://assets.mixkit.co/videos/12795/12795-720.mp4",
    poster: "https://assets.mixkit.co/videos/12795/12795-thumb-720-0.jpg",
    title: "Fat loss session",
    caption: "Treadmill-based cardio footage",
  },
  CARDIO: {
    src: "https://assets.mixkit.co/videos/49275/49275-720.mp4",
    poster: "https://assets.mixkit.co/videos/49275/49275-thumb-720-0.jpg",
    title: "Cardio session",
    caption: "Real gym cardio footage",
  },
  STRENGTH: {
    src: "https://assets.mixkit.co/videos/52093/52093-720.mp4",
    poster: "https://assets.mixkit.co/videos/52093/52093-thumb-720-0.jpg",
    title: "Strength session",
    caption: "Barbell lifting footage",
  },
  FLEXIBILITY: {
    src: "https://assets.mixkit.co/videos/44415/44415-720.mp4",
    poster: "https://assets.mixkit.co/videos/44415/44415-thumb-720-0.jpg",
    title: "Flexibility session",
    caption: "Stretching and mobility footage",
  },
  LOW_IMPACT: {
    src: "https://assets.mixkit.co/videos/44440/44440-720.mp4",
    poster: "https://assets.mixkit.co/videos/44440/44440-thumb-720-0.jpg",
    title: "Low impact session",
    caption: "Gentle gym stretching footage",
  },
  BEGINNER: {
    src: "https://assets.mixkit.co/active_storage/video_items/100526/1725383305/100526-video-720.mp4",
    poster: "https://assets.mixkit.co/active_storage/video_items/100526/1725383305/100526-video-thumb-720-0.jpg",
    title: "Beginner session",
    caption: "Warm-up and starter movement footage",
  },
  BALANCED: {
    src: "https://assets.mixkit.co/videos/606/606-720.mp4",
    poster: "https://assets.mixkit.co/videos/606/606-thumb-720-0.jpg",
    title: "Balanced session",
    caption: "General fitness footage",
  },
};

const getWorkoutVideo = (workoutType) => WORKOUT_VIDEOS[workoutType] || WORKOUT_VIDEOS.BALANCED;

const formatElapsedTime = (seconds) => {
  const safeSeconds = Math.max(0, Math.floor(seconds || 0));
  const minutes = String(Math.floor(safeSeconds / 60)).padStart(2, "0");
  const remaining = String(safeSeconds % 60).padStart(2, "0");
  return `${minutes}:${remaining}`;
};

export default function WorkoutDemoPlayer({ workoutType, routine, elapsedSeconds }) {
  const videoRef = useRef(null);
  const media = useMemo(() => getWorkoutVideo(workoutType), [workoutType]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return undefined;

    video.load();
    video.play().catch(() => {});

    return undefined;
  }, [media.src]);

  return (
    <div style={{ width: "100%" }}>
      <div
        style={{
          position: "relative",
          width: "100%",
          aspectRatio: "16 / 9",
          borderRadius: 10,
          overflow: "hidden",
          background: "#0b1020",
          border: "1px solid var(--border)",
        }}
      >
        <video
          ref={videoRef}
          key={media.src}
          src={media.src}
          poster={media.poster}
          muted
          playsInline
          autoPlay
          loop
          controls
          preload="metadata"
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            display: "block",
            background: "#0b1020",
          }}
        />

        <div
          style={{
            position: "absolute",
            left: 12,
            top: 12,
            padding: "6px 10px",
            borderRadius: 999,
            background: "rgba(11,16,32,0.72)",
            color: "#fff",
            fontSize: 12,
            fontWeight: 700,
            letterSpacing: 0,
            backdropFilter: "blur(8px)",
          }}
        >
          Real workout footage
        </div>

        <div
          style={{
            position: "absolute",
            right: 12,
            top: 12,
            padding: "6px 10px",
            borderRadius: 999,
            background: "rgba(11,16,32,0.72)",
            color: "#fff",
            fontSize: 12,
            fontWeight: 700,
            backdropFilter: "blur(8px)",
          }}
        >
          {formatElapsedTime(elapsedSeconds)}
        </div>
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", gap: 12, marginTop: 10, color: "var(--muted)", fontSize: 12 }}>
        <span>{media.title}</span>
        <span>{media.caption}</span>
      </div>

      <div style={{ marginTop: 8, fontSize: 13, color: "var(--muted)", lineHeight: 1.5 }}>
        {routine?.description || "Select a workout type to load a real workout clip and start timing yourself."}
      </div>
    </div>
  );
}
